	updateNode,
} from './model-operations.ts';
import { WORKLOAD_EXAMPLES } from './workload-examples.ts';

function ok<T extends { ok: boolean }>(result: T): Extract<T, { ok: true }> {
	if (!result.ok) throw new Error(`expected ok: ${JSON.stringify(result)}`);
	return result as Extract<T, { ok: true }>;
}

function sample(): ArchitectureModel {
	let model = createArchitectureModel('sample', 'Sample');
	model = ok(addNode(model, { kind: 'browser-app' })).model;
	model = ok(addNode(model, { kind: 'app-server' })).model;
	model = ok(addNode(model, { kind: 'relational-db' })).model;
	model = ok(addConnection(model, { from: 'browser-app', to: 'app-server' })).model;
	return ok(addConnection(model, { from: 'app-server', to: 'relational-db' })).model;
}

describe('model operations', () => {
	it('generates stable ids from the kind and puts nodes in their kind’s zone', () => {
		let model = sample();
		model = ok(addNode(model, { kind: 'app-server' })).model;
		expect(model.nodes.map((node) => node.id)).toEqual(['browser-app', 'app-server', 'relational-db', 'app-server-2']);
		expect(model.nodes.find((node) => node.id === 'relational-db')?.zone).toBe('data');
	});

	it('picks a protocol the target accepts by default', () => {
		const model = sample();
		expect(model.connections.map((connection) => connection.protocol)).toEqual(['http-rest', 'sql']);
	});

	it('removing a node removes its connections — nothing dangles', () => {
		const model = ok(removeNode(sample(), 'app-server')).model;
		expect(model.connections).toEqual([]);
		expect(parseArchitectureModel(model).ok).toBe(true);
	});

	it('refuses self-connections, duplicates, unknown nodes and disallowed placements, leaving the model untouched', () => {
		const model = sample();
		const before = JSON.stringify(model);
		expect(addConnection(model, { from: 'app-server', to: 'app-server' })).toEqual({
			ok: false,
			refusal: 'connection.self',
		});
		expect(addConnection(model, { from: 'browser-app', to: 'app-server' })).toEqual({
			ok: false,
			refusal: 'connection.duplicate',
		});
		expect(addConnection(model, { from: 'ghost', to: 'app-server' })).toEqual({ ok: false, refusal: 'node.unknown' });
		expect(updateNode(model, 'relational-db', { placement: 'browser-main-thread' })).toEqual({
			ok: false,
			refusal: 'placement.not-allowed',
		});
		expect(removeZone(model, 'data')).toEqual({ ok: false, refusal: 'zone.in-use' });
		expect(JSON.stringify(model)).toBe(before);
	});

	it('updates connection properties and removes connections', () => {
		let model = sample();
		const id = model.connections[0].id;
		model = ok(updateConnection(model, id, { authenticated: 'yes', failure_handling: 'timeout' })).model;
		expect(model.connections[0]).toMatchObject({ authenticated: 'yes', failure_handling: 'timeout' });
		model = ok(removeConnection(model, id)).model;
		expect(model.connections).toHaveLength(1);
	});

	it('a variant keeps node ids so a comparison can match them, and records why it exists', () => {
		const variant = deriveVariant(sample(), 'sample-b', 'Sample B', 'Add a worker');
		expect(variant).toMatchObject({ id: 'sample-b', derived_from: 'sample', change_reason: 'Add a worker' });
		expect(variant.nodes.map((node) => node.id)).toEqual(sample().nodes.map((node) => node.id));
	});
});

describe('parseArchitectureModel (untrusted input)', () => {
	it('accepts what the operations produce', () => {
		expect(parseArchitectureModel(sample()).ok).toBe(true);
	});

	it('refuses an unsupported format version', () => {
		const result = parseArchitectureModel({ ...sample(), format: 2 });
		expect(!result.ok && result.issues[0].message).toMatch(/unsupported format 2/);
	});

	it('refuses unknown keys instead of dropping them', () => {
		const model = sample() as unknown as Record<string, unknown>;
		const result = parseArchitectureModel({ ...model, script: 'alert(1)' });
		expect(!result.ok && result.issues.map((issue) => issue.path)).toContain('script');
	});

	it('refuses dangling references, duplicate ids and placements a kind cannot have', () => {
		const model = sample();
		const broken = {
			...model,
			nodes: [...model.nodes, { ...model.nodes[0] }, { ...model.nodes[2], id: 'db-2', placement: 'browser-worker' }],
			connections: [...model.connections, { ...model.connections[0], id: 'ghost-link', to: 'ghost' }],
		};
		const result = parseArchitectureModel(broken);
		const messages = !result.ok ? result.issues.map((issue) => issue.message).join('\n') : '';
		expect(messages).toMatch(/duplicate id "browser-app"/);
		expect(messages).toMatch(/node "ghost" does not exist/);
		expect(messages).toMatch(/cannot run as browser-worker/);
	});

	it('refuses oversized input rather than truncating it', () => {
		const model = sample();
		const many = Array.from({ length: MODEL_LIMITS.nodes + 1 }, (_, index) => ({
			...model.nodes[1],
			id: `n-${index}`,
		}));
		expect(parseArchitectureModel({ ...model, nodes: many, connections: [] }).ok).toBe(false);
		expect(parseArchitectureFile('x'.repeat(MODEL_LIMITS.fileBytes + 1)).ok).toBe(false);
	});

	it('refuses ids that are not kebab-case (no markup, no paths)', () => {
		const model = sample();
		const result = parseArchitectureModel({
			...model,
			nodes: [{ ...model.nodes[0], id: '<img src=x>' }],
			connections: [],
		});
		expect(result.ok).toBe(false);
	});

	it('handles corrupt files without throwing', () => {
		for (const text of ['', '{', 'null', '[]', '{"model": 3}', '{"model": {}, "extra": 1}']) {
			expect(parseArchitectureFile(text).ok).toBe(false);
		}
	});
});

describe('serialization', () => {
	it('export → import → export is byte-equal, and order of keyed collections does not matter', () => {
		const model = sample();
		const layout = layoutByZone(model);
		const text = stringifyArchitectureFile({ model, layout });
		const parsed = ok(parseArchitectureFile(text));
		expect(stringifyArchitectureFile(parsed.file)).toBe(text);
		const shuffled = { ...model, nodes: [...model.nodes].reverse() };
		expect(stringifyArchitectureFile({ model: shuffled, layout })).toBe(text);
	});

	it('keeps the layout separate and drops positions for nodes that do not exist', () => {
		const model = sample();
		const text = JSON.stringify({
			model,
			layout: { format: 1, positions: { 'browser-app': { x: 1, y: 2 }, ghost: { x: 0, y: 0 } } },
		});
		const parsed = ok(parseArchitectureFile(text));
		expect(parsed.file.layout?.positions).toEqual({ 'browser-app': { x: 1, y: 2 } });
		expect(JSON.stringify(parsed.file.model)).not.toMatch(/"x"/);
	});
});

describe('transfer from Explore', () => {
	for (const example of WORKLOAD_EXAMPLES) {
		it(`${example.id} produces a valid model`, () => {
			const model = modelFromRecommendation(exploreWorkload(DECISION_CATALOG, example.profile));
			expect(parseArchitectureModel(model).ok).toBe(true);
			expect(
				model.nodes.every((node) => node.decisions.every((id) => DECISION_CATALOG.decisions.some((d) => d.id === id))),
			).toBe(true);
		});
	}

	it('different workloads lead to different structures', () => {
		const shape = (id: string) => {
			const example = WORKLOAD_EXAMPLES.find((entry) => entry.id === id);
			if (!example) throw new Error(id);
			return modelFromRecommendation(exploreWorkload(DECISION_CATALOG, example.profile))
				.nodes.map((node) => node.kind)
				.sort();
		};
		expect(shape('local-image-processing')).toEqual(expect.arrayContaining(['browser-worker', 'wasm-module']));
		expect(shape('background-media-conversion')).toEqual(
			expect.arrayContaining(['background-worker', 'object-storage']),
		);
		expect(shape('scale-heavy-backend')).toContain('compute-service');
		expect(shape('lightweight-rest-api')).not.toContain('compute-service');
	});
});

describe('evolution example', () => {
	const stages = evolutionExample();

	it('every stage is a valid model derived from the one before, with a reason', () => {
		stages.forEach((stage, index) => {
			expect(parseArchitectureModel(stage).ok).toBe(true);
			if (index > 0) {
				expect(stage.derived_from).toBe(stages[index - 1].id);
				expect(stage.change_reason?.length).toBeGreaterThan(20);
			}
		});
	});

	it('adding components shows up as added complexity, not as a score', () => {
		const comparison = compareArchitectures(stages[1], stages[2]);
		expect(comparison.derived).toBe(true);
		expect(comparison.nodes.added.map((node) => node.id)).toEqual(['solver-service']);
		expect(comparison.variant.deployment_units.length).toBeGreaterThan(comparison.baseline.deployment_units.length);
		expect(comparison.requirements.added).toContain('container-host');
		expect(comparison.assessment.every((entry) => entry.basis === 'qualitative')).toBe(true);
		expect(comparison.assessment.find((entry) => entry.dimension === 'deployment-complexity')?.statement).toMatch(
			/adds 1 deployment unit/,
		);
	});

	it('comparison statements never present a number as a measured latency', () => {
		const comparison = compareArchitectures(stages[0], stages[3]);
		const latency = comparison.assessment.find((entry) => entry.dimension === 'latency')?.statement ?? '';
		expect(latency).toMatch(/not measured/);
		expect(latency).not.toMatch(/\d+\s*ms/);
	});

	it('the service stage leaves failure handling unknown, and the comparison reports it as introduced', () => {
		const comparison = compareArchitectures(stages[1], stages[2]);
		expect(comparison.findings.introduced.map((entry) => entry.code)).toContain('boundary.failure-unknown');
	});
});

/**
 * The architecture model: typed nodes, their placement and responsibilities, the connections
 * between them, the trust zones they sit in, and the decisions and patterns they link to.
 *
 * A diagram is a projection of this model, never its storage: coordinates live in a separate
 * `ArchitectureLayout` keyed by node id, so validators, docs and MCP tools read the model
 * without any knowledge of the canvas (the C4 / Structurizr model-vs-view split).
 *
 * Reading is fail-closed and treats input as untrusted (an imported file, a pasted draft, an
 * MCP argument): strict objects (an unknown key is refused, not dropped), bounded sizes,
 * kebab-case ids, closed vocabularies, no duplicate ids and no dangling references. Nothing
 * in a model is ever executed or rendered as markup. Writing is canonical — keyed collections
 * sorted by id, object keys sorted, tab-indented — so an export → import → export round trip
 * is byte-equal and two models diff cleanly.
 *
 * Not `version` (an optimistic-concurrency counter) nor `revision` (a stored snapshot):
 * `format` is the persisted shape number, as in `#lib/schemas/product-composition.ts`.
 */
import {
	NODE_KINDS,
	type NodeKind,
	PLACEMENTS,
	type Placement,
	PROTOCOLS,
	type Protocol,
	ZONE_KINDS,
	type ZoneKind,
} from './vocabulary.ts';

export const ARCHITECTURE_MODEL_FORMAT = 1;

/** Bounds on untrusted input. A model past them is refused, not truncated. */
export const MODEL_LIMITS = {
	nodes: 200,
	connections: 600,
	zones: 20,
	constraints: 50,
	listItems: 30,
	text: 2000,
	label: 120,
	/** Bytes of JSON text an import may be. */
	fileBytes: 1_000_000,
} as const;

export const AUTHENTICATION_STATES = ['yes', 'no', 'unknown'] as const;
export type AuthenticationState = (typeof AUTHENTICATION_STATES)[number];

export const FAILURE_HANDLING = [
	'unknown',
	'none',
	'timeout',
	'retry',
	'timeout-and-retry',
	'queue-redelivery',
] as const;
export type FailureHandling = (typeof FAILURE_HANDLING)[number];

export const CONNECTION_MODES = ['sync', 'async'] as const;
export type ConnectionMode = (typeof CONNECTION_MODES)[number];

export interface NodeTraits {
	/** The node's code or configuration holds credentials, keys or other server-only secrets. */
	holds_secrets: boolean;
	/** Moderate or heavy CPU per unit of work. */
	cpu_intensive: boolean;
	/** One unit of work runs for longer than a request should (seconds to hours). */
	long_running: boolean;
	/** The node keeps state between requests (connections, in-memory data). */
	stateful: boolean;
	/** The node needs a different runtime or language than the app (Rust, native code). */
	distinct_runtime: boolean;
}

export const NODE_TRAIT_IDS = [
	'holds_secrets',
	'cpu_intensive',
	'long_running',
	'stateful',
	'distinct_runtime',
] as const;

export interface ArchitectureZone {
	id: string;
	label: string;
	kind: ZoneKind;
}

export interface ArchitectureNode {
	id: string;
	kind: NodeKind;
	label: string;
	zone: string;
	placement: Placement;
	responsibilities: string[];
	traits: NodeTraits;
	/** Decision ids from the catalogue this node implements. */
	decisions: string[];
	/** Registry pattern ids that show how to build it. */
	patterns: string[];
}

export interface ArchitectureConnection {
	id: string;
	from: string;
	to: string;
	protocol: Protocol;
	mode: ConnectionMode;
	/** What flows, in words: "upload metadata", "rendered page". */
	data_flow: string;
	authenticated: AuthenticationState;
	failure_handling: FailureHandling;
}

export interface ArchitectureModel {
	format: typeof ARCHITECTURE_MODEL_FORMAT;
	id: string;
	name: string;
	description: string;
	/** The model this one was duplicated from, when it is a variant. */
	derived_from?: string;
	/** Why the variant exists — the evolution record. */
	change_reason?: string;
	zones: ArchitectureZone[];
	nodes: ArchitectureNode[];
	connections: ArchitectureConnection[];
	constraints: string[];
}

export interface ArchitectureLayout {
	format: typeof ARCHITECTURE_MODEL_FORMAT;
	positions: Record<string, { x: number; y: number }>;
}

/** What an exported file holds: the model, and optionally its layout. */
export interface ArchitectureFile {
	model: ArchitectureModel;
	layout?: ArchitectureLayout;
}

export interface ModelIssue {
	/** Dotted location: `nodes.3.zone`. */
	path: string;
	message: string;
}

export type ModelParse = { ok: true; model: ArchitectureModel } | { ok: false; issues: ModelIssue[] };

const ID = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_ID = 64;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

class Reader {
	issues: ModelIssue[] = [];

	fail(path: string, message: string): void {
		this.issues.push({ path, message });
	}

	strict(value: unknown, path: string, required: readonly string[], optional: readonly string[] = []) {
		if (!isRecord(value)) {
			this.fail(path, 'must be an object');
			return null;
		}
		for (const key of Object.keys(value)) {
			if (!required.includes(key) && !optional.includes(key)) this.fail(join(path, key), 'unknown key');
		}
		for (const key of required) {
			if (!(key in value)) this.fail(join(path, key), 'is required');
		}
		return value;
	}

	id(value: unknown, path: string): string {
		if (typeof value !== 'string' || value.length > MAX_ID || !ID.test(value)) {
			this.fail(path, 'must be a kebab-case id of at most 64 characters');
			return '';
		}
		return value;
	}

	text(value: unknown, path: string, max: number = MODEL_LIMITS.text, allowEmpty = true): string {
		if (typeof value !== 'string') {
			this.fail(path, 'must be a string');
			return '';
		}
		if (value.length > max) this.fail(path, `must be at most ${max} characters`);
		if (!allowEmpty && value.trim().length === 0) this.fail(path, 'must not be empty');
		return value;
	}

	pick<T extends string>(value: unknown, path: string, allowed: readonly T[]): T {
		if (typeof value !== 'string' || !(allowed as readonly string[]).includes(value)) {
			this.fail(path, `must be one of ${allowed.join('|')}`);
			return allowed[0];
		}
		return value as T;
	}

	list<T>(value: unknown, path: string, max: number, item: (entry: unknown, path: string) => T): T[] {
		if (!Array.isArray(value)) {
			this.fail(path, 'must be an array');
			return [];
		}
		if (value.length > max) {
			this.fail(path, `must have at most ${max} entries`);
			return [];
		}
		return value.map((entry, index) => item(entry, join(path, String(index))));
	}

	bool(value: unknown, path: string): boolean {
		if (typeof value !== 'boolean') this.fail(path, 'must be true or false');
		return value === true;
	}
}

function join(path: string, key: string): string {
	return path ? `${path}.${key}` : key;
}

function readZone(reader: Reader, value: unknown, path: string): ArchitectureZone {
	const record = reader.strict(value, path, ['id', 'label', 'kind']);
	if (!record) return { id: '', label: '', kind: 'client' };
	return {
		id: reader.id(record.id, join(path, 'id')),
		label: reader.text(record.label, join(path, 'label'), MODEL_LIMITS.label, false),
		kind: reader.pick(record.kind, join(path, 'kind'), ZONE_KINDS),
	};
}

function readTraits(reader: Reader, value: unknown, path: string): NodeTraits {
	const record = reader.strict(value, path, NODE_TRAIT_IDS);
	const traits = {} as NodeTraits;
	for (const trait of NODE_TRAIT_IDS) traits[trait] = record ? reader.bool(record[trait], join(path, trait)) : false;
	return traits;
}

function readNode(reader: Reader, value: unknown, path: string): ArchitectureNode {
	const record = reader.strict(value, path, [
		'id',
		'kind',
		'label',
		'zone',
		'placement',
		'responsibilities',
		'traits',
		'decisions',
		'patterns',
	]);
	if (!record) return emptyNode();
	const kind = reader.pick(record.kind, join(path, 'kind'), Object.keys(NODE_KINDS) as NodeKind[]);
	const placement = reader.pick(record.placement, join(path, 'placement'), PLACEMENTS);
	const textItem = (entry: unknown, at: string) => reader.text(entry, at, MODEL_LIMITS.text, false);
	return {
		id: reader.id(record.id, join(path, 'id')),
		kind,
		label: reader.text(record.label, join(path, 'label'), MODEL_LIMITS.label, false),
		zone: reader.id(record.zone, join(path, 'zone')),
		placement,
		responsibilities: reader.list(
			record.responsibilities,
			join(path, 'responsibilities'),
			MODEL_LIMITS.listItems,
			textItem,
		),
		traits: readTraits(reader, record.traits, join(path, 'traits')),
		decisions: reader.list(record.decisions, join(path, 'decisions'), MODEL_LIMITS.listItems, (entry, at) =>
			reader.id(entry, at),
		),
		patterns: reader.list(record.patterns, join(path, 'patterns'), MODEL_LIMITS.listItems, (entry, at) =>
			reader.id(entry, at),
		),
	};
}

function readConnection(reader: Reader, value: unknown, path: string): ArchitectureConnection {
	const record = reader.strict(value, path, [
		'id',
		'from',
		'to',
		'protocol',
		'mode',
		'data_flow',
		'authenticated',
		'failure_handling',
	]);
	if (!record) return emptyConnection();
	return {
		id: reader.id(record.id, join(path, 'id')),
		from: reader.id(record.from, join(path, 'from')),
		to: reader.id(record.to, join(path, 'to')),
		protocol: reader.pick(record.protocol, join(path, 'protocol'), PROTOCOLS),
		mode: reader.pick(record.mode, join(path, 'mode'), CONNECTION_MODES),
		data_flow: reader.text(record.data_flow, join(path, 'data_flow')),
		authenticated: reader.pick(record.authenticated, join(path, 'authenticated'), AUTHENTICATION_STATES),
		failure_handling: reader.pick(record.failure_handling, join(path, 'failure_handling'), FAILURE_HANDLING),
	};
}

function emptyNode(): ArchitectureNode {
	return {
		id: '',
		kind: 'app-server',
		label: '',
		zone: '',
		placement: 'server-request',
		responsibilities: [],
		traits: {
			holds_secrets: false,
			cpu_intensive: false,
			long_running: false,
			stateful: false,
			distinct_runtime: false,
		},
		decisions: [],
		patterns: [],
	};
}

function emptyConnection(): ArchitectureConnection {
	return {
		id: '',
		from: '',
		to: '',
		protocol: 'http-rest',
		mode: 'sync',
		data_flow: '',
		authenticated: 'unknown',
		failure_handling: 'unknown',
	};
}

/** Graph integrity: ids unique per collection, every reference resolves, placement allowed for the kind. */
function checkIntegrity(model: ArchitectureModel, reader: Reader): void {
	const unique = (collection: string, items: { id: string }[]) => {
		const seen = new Set<string>();
		items.forEach((item, index) => {
			if (item.id && seen.has(item.id)) reader.fail(`${collection}.${index}.id`, `duplicate id "${item.id}"`);
			seen.add(item.id);
		});
		return seen;
	};
	const zoneIds = unique('zones', model.zones);
	const nodeIds = unique('nodes', model.nodes);
	unique('connections', model.connections);
	model.nodes.forEach((node, index) => {
		if (node.zone && !zoneIds.has(node.zone)) reader.fail(`nodes.${index}.zone`, `zone "${node.zone}" does not exist`);
		const allowed = NODE_KINDS[node.kind].placements as readonly Placement[];
		if (!allowed.includes(node.placement)) {
			reader.fail(`nodes.${index}.placement`, `a ${node.kind} cannot run as ${node.placement}`);
		}
	});
	model.connections.forEach((connection, index) => {
		for (const end of ['from', 'to'] as const) {
			if (connection[end] && !nodeIds.has(connection[end])) {
				reader.fail(`connections.${index}.${end}`, `node "${connection[end]}" does not exist`);
			}
		}
		if (connection.from && connection.from === connection.to) {
			reader.fail(`connections.${index}`, 'a connection cannot join a node to itself');
		}
	});
}

export function parseArchitectureModel(input: unknown): ModelParse {
	const reader = new Reader();
	const record = reader.strict(
		input,
		'',
		['format', 'id', 'name', 'description', 'zones', 'nodes', 'connections', 'constraints'],
		['derived_from', 'change_reason'],
	);
	if (!record) return { ok: false, issues: reader.issues };
	if (record.format !== ARCHITECTURE_MODEL_FORMAT) {
		return {
			ok: false,
			issues: [
				{
					path: 'format',
					message: `unsupported format ${String(record.format)} (this version reads ${ARCHITECTURE_MODEL_FORMAT})`,
				},
			],
		};
	}
	const model: ArchitectureModel = {
		format: ARCHITECTURE_MODEL_FORMAT,
		id: reader.id(record.id, 'id'),
		name: reader.text(record.name, 'name', MODEL_LIMITS.label, false),
		description: reader.text(record.description, 'description'),
		zones: reader.list(record.zones, 'zones', MODEL_LIMITS.zones, (entry, at) => readZone(reader, entry, at)),
		nodes: reader.list(record.nodes, 'nodes', MODEL_LIMITS.nodes, (entry, at) => readNode(reader, entry, at)),
		connections: reader.list(record.connections, 'connections', MODEL_LIMITS.connections, (entry, at) =>
			readConnection(reader, entry, at),
		),
		constraints: reader.list(record.constraints, 'constraints', MODEL_LIMITS.constraints, (entry, at) =>
			reader.text(entry, at, MODEL_LIMITS.text, false),
		),
	};
	if (record.derived_from !== undefined) model.derived_from = reader.id(record.derived_from, 'derived_from');
	if (record.change_reason !== undefined) model.change_reason = reader.text(record.change_reason, 'change_reason');
	if (reader.issues.length === 0) checkIntegrity(model, reader);
	return reader.issues.length > 0 ? { ok: false, issues: reader.issues } : { ok: true, model };
}

export type LayoutParse = { ok: true; layout: ArchitectureLayout } | { ok: false; issues: ModelIssue[] };

/** Layout positions for unknown nodes are dropped (a layout is cosmetic); malformed positions are refused. */
export function parseArchitectureLayout(input: unknown, model: ArchitectureModel): LayoutParse {
	const reader = new Reader();
	const record = reader.strict(input, '', ['format', 'positions']);
	if (!record) return { ok: false, issues: reader.issues };
	if (record.format !== ARCHITECTURE_MODEL_FORMAT)
		return { ok: false, issues: [{ path: 'format', message: 'unsupported format' }] };
	if (!isRecord(record.positions)) return { ok: false, issues: [{ path: 'positions', message: 'must be an object' }] };
	const nodeIds = new Set(model.nodes.map((node) => node.id));
	const positions: ArchitectureLayout['positions'] = {};
	for (const [id, value] of Object.entries(record.positions)) {
		const position = reader.strict(value, `positions.${id}`, ['x', 'y']);
		if (!position) continue;
		const { x, y } = position;
		if (
			typeof x !== 'number' ||
			typeof y !== 'number' ||
			!Number.isFinite(x) ||
			!Number.isFinite(y) ||
			Math.abs(x) > 1e6 ||
			Math.abs(y) > 1e6
		) {
			reader.fail(`positions.${id}`, 'x and y must be finite numbers within ±1e6');
			continue;
		}
		if (nodeIds.has(id)) positions[id] = { x, y };
	}
	return reader.issues.length > 0
		? { ok: false, issues: reader.issues }
		: { ok: true, layout: { format: ARCHITECTURE_MODEL_FORMAT, positions } };
}

export type FileParse = { ok: true; file: ArchitectureFile } | { ok: false; issues: ModelIssue[] };

/** Read an exported file's text: size-bounded, JSON, then model, then (optional) layout. */
export function parseArchitectureFile(text: string): FileParse {
	if (text.length > MODEL_LIMITS.fileBytes) {
		return { ok: false, issues: [{ path: '', message: `file is larger than ${MODEL_LIMITS.fileBytes} characters` }] };
	}
	let data: unknown;
	try {
		data = JSON.parse(text);
	} catch {
		return { ok: false, issues: [{ path: '', message: 'not valid JSON' }] };
	}
	if (!isRecord(data)) return { ok: false, issues: [{ path: '', message: 'must be an object with a "model"' }] };
	for (const key of Object.keys(data)) {
		if (key !== 'model' && key !== 'layout') return { ok: false, issues: [{ path: key, message: 'unknown key' }] };
	}
	const model = parseArchitectureModel(data.model);
	if (!model.ok)
		return { ok: false, issues: model.issues.map((issue) => ({ ...issue, path: join('model', issue.path) })) };
	if (data.layout === undefined) return { ok: true, file: { model: model.model } };
	const layout = parseArchitectureLayout(data.layout, model.model);
	if (!layout.ok)
		return { ok: false, issues: layout.issues.map((issue) => ({ ...issue, path: join('layout', issue.path) })) };
	return { ok: true, file: { model: model.model, layout: layout.layout } };
}

const KEYED = new Set(['zones', 'nodes', 'connections']);

function canonical(value: unknown, key?: string): unknown {
	if (Array.isArray(value)) {
		const items = value.map((item) => canonical(item));
		if (key && KEYED.has(key)) {
			return (items as { id: string }[]).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
		}
		return items;
	}
	if (isRecord(value)) {
		return Object.fromEntries(
			Object.keys(value)
				.sort()
				.map((entry) => [entry, canonical(value[entry], entry)]),
		);
	}
	return value;
}

/** Canonical, byte-stable text of a file: the same content always produces the same bytes. */
export function stringifyArchitectureFile(file: ArchitectureFile): string {
	return `${JSON.stringify(canonical(file), null, '\t')}\n`;
}

import { describe, expect, it } from 'vitest';
import registryJson from '../registry.json';
import type { ArchitectureModel } from './architecture-model.ts';
import { checkArchitecture, checkDesign, checkSecurity } from './checks.ts';
import { FINDING_SPECS, type FindingCode } from './findings.ts';
import {
	addConnection,
	addNode,
	createArchitectureModel,
	type NewConnection,
	type NewNode,
	updateNode,
} from './model-operations.ts';

function build(nodes: NewNode[], connections: NewConnection[] = []): ArchitectureModel {
	let model = createArchitectureModel('test', 'Test');
	for (const node of nodes) {
		const result = addNode(model, node);
		if (!result.ok) throw new Error(result.refusal);
		model = result.model;
	}
	for (const connection of connections) {
		const result = addConnection(model, connection);
		if (!result.ok) throw new Error(result.refusal);
		model = result.model;
	}
	return model;
}

const codes = (model: ArchitectureModel) => checkArchitecture(model).map((entry) => entry.code);

/** A clean three-tier baseline: every boundary authenticated with a stated failure policy. */
function clean(): ArchitectureModel {
	return build(
		[{ kind: 'browser-app' }, { kind: 'app-server', traits: { holds_secrets: true } }, { kind: 'relational-db' }],
		[
			{ from: 'browser-app', to: 'app-server', authenticated: 'yes', failure_handling: 'timeout' },
			{ from: 'app-server', to: 'relational-db', authenticated: 'yes', failure_handling: 'timeout' },
		],
	);
}

describe('engineering checks', () => {
	it('a clean baseline has no findings (control for every test below)', () => {
		expect(checkArchitecture(clean())).toEqual([]);
	});

	it('detects a server-only secret on a browser-executed component', () => {
		const result = updateNode(clean(), 'browser-app', { traits: { holds_secrets: true } });
		if (!result.ok) throw new Error(result.refusal);
		expect(checkSecurity(result.model).map((entry) => entry.code)).toEqual(['secret.client-exposed']);
	});

	it('detects an unauthenticated trust-boundary crossing, and keeps unknown as unknown', () => {
		const no = build(
			[{ kind: 'browser-app' }, { kind: 'api-endpoint' }],
			[{ from: 'browser-app', to: 'api-endpoint', authenticated: 'no', failure_handling: 'timeout' }],
		);
		const unknown = build(
			[{ kind: 'browser-app' }, { kind: 'api-endpoint' }],
			[{ from: 'browser-app', to: 'api-endpoint', failure_handling: 'timeout' }],
		);
		expect(codes(no)).toContain('boundary.unauthenticated');
		expect(checkArchitecture(unknown).find((entry) => entry.code === 'boundary.auth-unknown')?.severity).toBe(
			'unknown',
