				{ kind: 'compute-service' },
			],
			[
				{
					from: 'browser-app',
					to: 'compute-service',
					protocol: 'http-rest',
					authenticated: 'no',
					failure_handling: 'none',
				},
			],
		);
		for (const entry of checkArchitecture(model)) {
			expect(`${entry.detected} ${entry.why} ${entry.fix}`).not.toMatch(/\d+\s*(ms|s|%|x|×)\b/);
		}
	});

	it('every finding links only to registry patterns', () => {
		const known = new Set((registryJson as { patterns: { id: string }[] }).patterns.map((pattern) => pattern.id));
		const model = build(
			[
				{ kind: 'browser-app', traits: { holds_secrets: true, cpu_intensive: true } },
				{ kind: 'app-server', traits: { long_running: true } },
				{ kind: 'compute-service' },
				{ kind: 'relational-db' },
				{ kind: 'cache' },
			],
			[
				{ from: 'browser-app', to: 'relational-db', protocol: 'sql', authenticated: 'no' },
				{ from: 'browser-app', to: 'app-server', protocol: 'websocket', authenticated: 'unknown' },
				{ from: 'app-server', to: 'compute-service', authenticated: 'yes', failure_handling: 'none' },
				{ from: 'compute-service', to: 'relational-db', authenticated: 'yes' },
				{ from: 'app-server', to: 'relational-db', protocol: 'http-rest', authenticated: 'yes' },
			],
		);
		const findings = checkArchitecture(model);
		const seen = new Set(findings.map((entry) => entry.code));
		// This model is built to exercise every code but the scheduled-stateful variant of runtime.unsupported.
		expect([...seen].sort()).toEqual((Object.keys(FINDING_SPECS) as FindingCode[]).sort());
		for (const entry of findings) for (const id of entry.patterns) expect(known.has(id), id).toBe(true);
	});
});

/**
 * Engineering checks: an architecture model in, sorted findings out. Each check is a pure,
 * static function over the model's declared facts — the architecture-level counterpart of
 * v10r's own `*.gate.test.ts` fitness functions. Nothing here measures, runs or estimates
 * performance, and no finding may claim a number.
 *
 * The model is assumed to have passed `parseArchitectureModel` (integrity holds: every
 * reference resolves). Security checks are separate functions from the rest, so they can be
 * read, tested and reported on their own.
 */
import type { ArchitectureConnection, ArchitectureModel, ArchitectureNode } from './architecture-model.ts';
import { type ArchitectureFinding, finding, sortFindings } from './findings.ts';
import { CLIENT_PLACEMENTS, NETWORK_PROTOCOLS, NODE_KINDS, type NodeKind, type Protocol } from './vocabulary.ts';

const DATA_KINDS: readonly NodeKind[] = ['relational-db', 'graph-db', 'cache', 'object-storage'];
/** Data stores the browser may legitimately reach directly — object storage through a signed URL. */
const CLIENT_REACHABLE_STORES: readonly NodeKind[] = ['object-storage'];

interface Context {
	model: ArchitectureModel;
	byId: Map<string, ArchitectureNode>;
	zoneKind: Map<string, string>;
}

function isClient(node: ArchitectureNode): boolean {
	return CLIENT_PLACEMENTS.includes(node.placement);
}

function crossesNetwork(connection: ArchitectureConnection): boolean {
	return NETWORK_PROTOCOLS.includes(connection.protocol);
}

function crossesZone(context: Context, connection: ArchitectureConnection): boolean {
	const from = context.byId.get(connection.from);
	const to = context.byId.get(connection.to);
	return !!from && !!to && from.zone !== to.zone;
}

/**
 * A boundary between separately running parts the design owns or depends on: the device to
 * the server, the app to a worker or service, anything to a third party. Calls to the app's
 * own managed data stores are left to the driver's defaults and not flagged here.
 */
function isServiceBoundary(from: ArchitectureNode, to: ArchitectureNode): boolean {
	const target = NODE_KINDS[to.kind].deploysAs;
	if (to.kind === 'external-service') return true;
	if (target === 'service' || target === 'worker') return from.id !== to.id;
	return isClient(from) && !isClient(to) && target === 'app';
}

function connectionSubject(connection: ArchitectureConnection): string {
	return `connections/${connection.id}`;
}

// ── Security ────────────────────────────────────────────────────────────────

function secretsOnClient(context: Context): ArchitectureFinding[] {
	return context.model.nodes
		.filter((node) => node.traits.holds_secrets && isClient(node))
		.map((node) =>
			finding('secret.client-exposed', `nodes/${node.id}`, {
				detected: `"${node.label}" holds server-only secrets but runs on the user's device (${node.placement}).`,
				why: 'Everything shipped to a browser can be read by its user: bundles, workers and wasm modules are public.',
				constraint: 'Secrets and authorization decisions never execute on the device.',
				fix: 'Move the secret-holding work to an application-zone node (a server request or service) and call it from the browser.',
				patterns: ['multi-client-core', 'identity-route-guards'],
			}),
		);
}

function boundaryAuthentication(context: Context): ArchitectureFinding[] {
	const findings: ArchitectureFinding[] = [];
	for (const connection of context.model.connections) {
		const from = context.byId.get(connection.from);
		const to = context.byId.get(connection.to);
		if (!from || !to || !crossesZone(context, connection) || !crossesNetwork(connection)) continue;
		// Only crossings *into* a more trusted zone need the caller authenticated; data leaving to a client is the server's choice.
		const intoTrusted = isClient(from) || context.zoneKind.get(from.zone) === 'third-party';
		if (!intoTrusted) continue;
		if (connection.authenticated === 'no') {
			findings.push(
				finding('boundary.unauthenticated', connectionSubject(connection), {
					detected: `"${from.label}" → "${to.label}" crosses a trust boundary (${connection.protocol}) without authentication.`,
					why: 'Anyone who can reach the endpoint can call it; the client is not a trust boundary.',
					constraint:
						'Every crossing into a more trusted zone authenticates the caller and authorizes the operation on the server.',
					fix: 'Authenticate the connection (session cookie, bearer token, signed webhook) and authorize in the server-side domain.',
					patterns: ['identity-route-guards', 'identity-capability-grants', 'anti-abuse-rate-limiting'],
				}),
			);
		} else if (connection.authenticated === 'unknown') {
			findings.push(
				finding('boundary.auth-unknown', connectionSubject(connection), {
					detected: `"${from.label}" → "${to.label}" crosses a trust boundary and its authentication is not stated.`,
					why: 'Whether this is a problem depends on a fact the model does not record.',
					constraint: 'Every crossing into a more trusted zone authenticates the caller.',
					fix: 'State whether the connection is authenticated; if it is public on purpose, mark it "no" and expect a finding to accept.',
					patterns: ['identity-route-guards'],
				}),
			);
		}
	}
	return findings;
}

function clientDirectData(context: Context): ArchitectureFinding[] {
	return context.model.connections.flatMap((connection) => {
		const from = context.byId.get(connection.from);
		const to = context.byId.get(connection.to);
		if (!from || !to || !isClient(from) || !DATA_KINDS.includes(to.kind) || CLIENT_REACHABLE_STORES.includes(to.kind)) {
			return [];
		}
		return [
			finding('client.direct-data-access', connectionSubject(connection), {
				detected: `"${from.label}" on the device talks to "${to.label}" directly.`,
				why: 'A database credential in the browser is a public credential; row access can no longer be authorized per user.',
				constraint: 'Data stores are reached through the application zone, which authorizes every operation.',
				fix: 'Route the access through an API endpoint or server load function that owns the query.',
				patterns: ['multi-client-core', 'databases-queries-mutations-split'],
			}),
		];
	});
}

export function checkSecurity(model: ArchitectureModel): ArchitectureFinding[] {
	const context = contextOf(model);
	return sortFindings([...secretsOnClient(context), ...boundaryAuthentication(context), ...clientDirectData(context)]);
}

// ── Runtime, communication, data, structure ─────────────────────────────────

function mainThreadCpu(context: Context): ArchitectureFinding[] {
	return context.model.nodes
		.filter((node) => node.placement === 'browser-main-thread' && node.traits.cpu_intensive)
		.map((node) =>
			finding('main-thread.cpu', `nodes/${node.id}`, {
				detected: `"${node.label}" does CPU-intensive work on the browser main thread.`,
				why: 'While it runs, input and rendering wait; on slow phones a heavy task is visible jank. A heuristic: short bursts may be fine.',
				constraint: 'Interactive work keeps each main-thread task inside the interaction budget.',
				fix: 'Move the computation into a browser worker (and transfer buffers), or measure and show it stays under budget.',
				patterns: ['main-thread-budget', 'velocity-idle-work'],
			}),
		);
}

function longRunningInRequest(context: Context): ArchitectureFinding[] {
	return context.model.nodes
		.filter((node) => node.traits.long_running && (node.placement === 'server-request' || node.placement === 'edge'))
		.map((node) =>
			finding('request.long-running', `nodes/${node.id}`, {
				detected: `"${node.label}" is long-running but placed in a short-lived request handler (${node.placement}).`,
				why: 'Serverless request handlers are cut off at the host’s duration limit, and the user waits on an open request.',
				constraint: 'Work that outlives a request runs as a job with a status, not inside the request.',
				fix: 'Enqueue it for a background worker (database outbox) and report progress by status or SSE.',
				patterns: ['jobs-scheduler', 'notifications-router-outbox', 'durable-step-execution'],
			}),
		);
}

function unsupportedRuntime(context: Context): ArchitectureFinding[] {
	const findings: ArchitectureFinding[] = [];
	for (const connection of context.model.connections) {
		const to = context.byId.get(connection.to);
		if (!to) continue;
		if (connection.protocol === 'websocket' && (to.placement === 'server-request' || to.placement === 'edge')) {
			findings.push(
				finding('runtime.unsupported', connectionSubject(connection), {
					detected: `A WebSocket terminates at "${to.label}", which runs as ${to.placement}.`,
					why: 'Short-lived request handlers cannot hold a connection open between requests.',
					constraint: 'Persistent connections need a persistent process.',
					fix: 'Place the target on a persistent server process, or switch to SSE plus ordinary requests.',
					patterns: ['notifications-sse-stream', 'architecture-deployment'],
				}),
			);
		}
	}
	for (const node of context.model.nodes) {
		if (node.kind === 'background-worker' && node.traits.stateful && node.placement === 'background-worker') {
			// A scheduled job on serverless keeps no state between runs; flag only when the model says it must.
			findings.push(
				finding('runtime.unsupported', `nodes/${node.id}`, {
					detected: `"${node.label}" is a scheduled background worker but is marked as keeping state between runs.`,
					why: 'Scheduled jobs start fresh each run; in-memory state is lost.',
					constraint:
						'State that must survive between runs lives in a store, or the worker runs as a persistent process.',
					fix: 'Keep the state in Postgres, or set the placement to a persistent server process.',
					patterns: ['jobs-scheduler'],
				}),
			);
		}
	}
	return findings;
}

function protocolCompatibility(context: Context): ArchitectureFinding[] {
	return context.model.connections.flatMap((connection) => {
		const to = context.byId.get(connection.to);
		if (!to) return [];
		const accepts = NODE_KINDS[to.kind].accepts as readonly Protocol[];
		if (accepts.includes(connection.protocol)) return [];
		return [
			finding('protocol.incompatible', connectionSubject(connection), {
				detected: `"${to.label}" (${NODE_KINDS[to.kind].label}) cannot be reached over ${connection.protocol}.`,
				why: 'The connection describes a call the target does not speak, so the design cannot be built as drawn.',
				constraint: `A ${NODE_KINDS[to.kind].label} accepts: ${accepts.join(', ')}.`,
				fix: `Change the protocol to one the target accepts, or put an adapter node between them.`,
				patterns: NODE_KINDS[to.kind].patterns.slice(0, 2),
			}),
		];
	});
}

function failureHandling(context: Context): ArchitectureFinding[] {
	const findings: ArchitectureFinding[] = [];
	for (const connection of context.model.connections) {
		const from = context.byId.get(connection.from);
		const to = context.byId.get(connection.to);
		if (!from || !to || !crossesNetwork(connection)) continue;
		if (!isServiceBoundary(from, to)) continue;
		if (connection.failure_handling === 'unknown') {
			findings.push(
				finding('boundary.failure-unknown', connectionSubject(connection), {
					detected: `"${from.label}" → "${to.label}" crosses a network boundary and its failure handling is not stated.`,
					why: 'Across a network the callee can be slow, down or cold; what the caller does then is part of the design.',
					constraint: 'Every network boundary states a deadline and a retry policy (or why none is needed).',
					fix: 'State the failure handling: a timeout, retries for idempotent calls, or queue redelivery.',
					patterns: ['resilience-policy', 'deadline-propagation'],
				}),
			);
		} else if (connection.failure_handling === 'none' && connection.mode === 'sync') {
			findings.push(
				finding('boundary.no-failure-handling', connectionSubject(connection), {
					detected: `"${from.label}" → "${to.label}" is a synchronous network call with no failure handling.`,
					why: 'Without a deadline a slow callee holds the caller’s request open until the host kills it.',
					constraint: 'Every synchronous network call has a deadline.',
					fix: 'Add a timeout; retry only idempotent operations, with backoff.',
					patterns: ['resilience-policy', 'deadline-propagation'],
				}),
			);
		}
	}
	return findings;
}

function unjustifiedService(context: Context): ArchitectureFinding[] {
	return context.model.nodes
		.filter(
			(node) =>
				node.kind === 'compute-service' &&
				!node.traits.cpu_intensive &&
				!node.traits.long_running &&
				!node.traits.distinct_runtime &&
				!node.traits.stateful,
		)
		.map((node) =>
			finding('boundary.unjustified-service', `nodes/${node.id}`, {
				detected: `"${node.label}" is a separately deployed service with no stated reason (no CPU-intensive, long-running, stateful or distinct-runtime trait).`,
				why: 'A separate deployment adds a network hop, a credential, a contract and a failure mode to every call.',
				constraint: 'Prefer the simpler architecture unless a requirement justifies the extra unit.',
				fix: 'Fold it into the application as a domain module, or record the trait that justifies it.',
				patterns: ['multi-client-core', 'architecture-external-service'],
			}),
		);
}

function sharedDataOwnership(context: Context): ArchitectureFinding[] {
	const findings: ArchitectureFinding[] = [];
	for (const store of context.model.nodes) {
		if (!DATA_KINDS.includes(store.kind) || store.kind === 'cache') continue;
		const units = new Set(
			context.model.connections
				.filter((connection) => connection.to === store.id)
				.map((connection) => context.byId.get(connection.from))
				.filter((node): node is ArchitectureNode => !!node)
				.map((node) =>
					NODE_KINDS[node.kind].deploysAs === 'service' ? `service:${node.id}` : NODE_KINDS[node.kind].deploysAs,
				),
		);
		const services = [...units].filter((unit) => unit.startsWith('service:'));
		if (services.length > 0 && units.size > 1) {
			findings.push(
				finding('data.shared-ownership', `nodes/${store.id}`, {
					detected: `"${store.label}" is accessed by several deployment units (${[...units].sort().join(', ')}).`,
					why: 'When two deployments read and write the same tables, neither owns the schema, and a change in one breaks the other.',
					constraint: 'Each data store has one owning deployment unit; others go through its interface.',
					fix: 'Give the store one owner and let the other unit call that owner, or split the data.',
					patterns: ['architecture-external-service', 'databases-queries-mutations-split'],
				}),
			);
		}
	}
	return findings;
}

function isolatedNodes(context: Context): ArchitectureFinding[] {
	if (context.model.nodes.length < 2) return [];
	const touched = new Set(context.model.connections.flatMap((connection) => [connection.from, connection.to]));
	return context.model.nodes
		.filter((node) => !touched.has(node.id))
		.map((node) =>
			finding('node.isolated', `nodes/${node.id}`, {
				detected: `"${node.label}" has no connections.`,
				why: 'A component nothing talks to is either missing its connections or not needed.',
				constraint: 'Every component has a stated relationship to the rest of the system.',
				fix: 'Connect it, or remove it.',
				patterns: [],
			}),
		);
}

function contextOf(model: ArchitectureModel): Context {
	return {
		model,
		byId: new Map(model.nodes.map((node) => [node.id, node])),
		zoneKind: new Map(model.zones.map((zone) => [zone.id, zone.kind])),
	};
}

/** Every check that is not a security check. */
export function checkDesign(model: ArchitectureModel): ArchitectureFinding[] {
	const context = contextOf(model);
	return sortFindings([
		...mainThreadCpu(context),
		...longRunningInRequest(context),
		...unsupportedRuntime(context),
		...protocolCompatibility(context),
		...failureHandling(context),
		...unjustifiedService(context),
		...sharedDataOwnership(context),
		...isolatedNodes(context),
	]);
}

/** All findings, sorted: security and design checks together. */
export function checkArchitecture(model: ArchitectureModel): ArchitectureFinding[] {
	return sortFindings([...checkSecurity(model), ...checkDesign(model)]);
}

/**
 * Compare two architecture models — typically a baseline and a variant derived from it.
 *
 * Everything counted here is read off the models: nodes, placements, connections, zones,
 * deployment units, network boundaries, operational requirements and findings. Latency and
 * complexity are described *qualitatively*, from those counts, and every such statement is
 * marked `basis: 'qualitative'` — no number in a comparison is a measurement, and none is
 * presented as one. Adding a component is never scored as an improvement by itself.
 */
import type { PatternRequirement } from '../schema.ts';
import type { ArchitectureConnection, ArchitectureModel, ArchitectureNode } from './architecture-model.ts';
import { checkArchitecture } from './checks.ts';
import type { ArchitectureFinding } from './findings.ts';
import { NETWORK_PROTOCOLS, NODE_KINDS } from './vocabulary.ts';

export interface NodeChange {
	id: string;
	label: string;
	changes: string[];
}

export interface ModelSummary {
	id: string;
	name: string;
	/** What gets deployed and operated: `app`, plus one entry per worker or service node. */
	deployment_units: string[];
	/** Managed or third-party systems the design depends on. */
	managed_dependencies: string[];
	network_connections: number;
	synchronous_network_connections: number;
	trust_boundary_crossings: number;
	requirements: PatternRequirement[];
	findings: ArchitectureFinding[];
}

export interface QualitativeAssessment {
	dimension: 'deployment-complexity' | 'latency' | 'operations' | 'security' | 'risk';
	statement: string;
	basis: 'qualitative';
}

export interface ArchitectureComparison {
	baseline: ModelSummary;
	variant: ModelSummary;
	change_reason?: string;
	derived: boolean;
	nodes: { added: ArchitectureNode[]; removed: ArchitectureNode[]; changed: NodeChange[] };
	placements: { id: string; label: string; from: string; to: string }[];
	connections: { added: ArchitectureConnection[]; removed: ArchitectureConnection[]; changed: NodeChange[] };
	zones: { added: string[]; removed: string[] };
	requirements: { added: PatternRequirement[]; removed: PatternRequirement[] };
	findings: { introduced: ArchitectureFinding[]; resolved: ArchitectureFinding[] };
	assessment: QualitativeAssessment[];
}

const compareText = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

function summarize(model: ArchitectureModel): ModelSummary {
	const byId = new Map(model.nodes.map((node) => [node.id, node]));
	const units = new Set<string>();
	const managed: string[] = [];
	for (const node of model.nodes) {
		const deploysAs = NODE_KINDS[node.kind].deploysAs;
		if (deploysAs === 'app') units.add('app');
		else if (deploysAs === 'managed') managed.push(node.id);
		else units.add(`${deploysAs}:${node.id}`);
	}
	const network = model.connections.filter((connection) => NETWORK_PROTOCOLS.includes(connection.protocol));
	const crossings = model.connections.filter((connection) => {
		const from = byId.get(connection.from);
		const to = byId.get(connection.to);
		return !!from && !!to && from.zone !== to.zone;
	});
	const requirements = new Set<PatternRequirement>();
	for (const node of model.nodes)
		for (const requirement of NODE_KINDS[node.kind].requires) requirements.add(requirement);
	return {
		id: model.id,
		name: model.name,
		deployment_units: [...units].sort(compareText),
		managed_dependencies: managed.sort(compareText),
		network_connections: network.length,
		synchronous_network_connections: network.filter((connection) => connection.mode === 'sync').length,
		trust_boundary_crossings: crossings.length,
		requirements: [...requirements].sort(compareText),
		findings: checkArchitecture(model),
	};
}

function nodeChanges(a: ArchitectureNode, b: ArchitectureNode): string[] {
	const changes: string[] = [];
	if (a.label !== b.label) changes.push(`label "${a.label}" → "${b.label}"`);
	if (a.zone !== b.zone) changes.push(`zone ${a.zone} → ${b.zone}`);
	if (a.placement !== b.placement) changes.push(`placement ${a.placement} → ${b.placement}`);
	if (a.responsibilities.join('\n') !== b.responsibilities.join('\n')) changes.push('responsibilities changed');
	for (const trait of Object.keys(a.traits) as (keyof ArchitectureNode['traits'])[]) {
		if (a.traits[trait] !== b.traits[trait]) changes.push(`${trait} ${a.traits[trait]} → ${b.traits[trait]}`);
	}
	if (a.patterns.join() !== b.patterns.join()) changes.push('linked patterns changed');
	if (a.decisions.join() !== b.decisions.join()) changes.push('linked decisions changed');
	return changes;
}

function connectionChanges(a: ArchitectureConnection, b: ArchitectureConnection): string[] {
	const changes: string[] = [];
	for (const field of ['protocol', 'mode', 'data_flow', 'authenticated', 'failure_handling'] as const) {
		if (a[field] !== b[field]) changes.push(`${field} ${a[field] || '—'} → ${b[field] || '—'}`);
	}
	return changes;
}

const findingKey = (entry: ArchitectureFinding): string => `${entry.code} ${entry.subject}`;

function diffKeyed<T extends { id: string }>(a: T[], b: T[]) {
	const before = new Map(a.map((item) => [item.id, item]));
	const after = new Map(b.map((item) => [item.id, item]));
	return {
		added: b.filter((item) => !before.has(item.id)),
		removed: a.filter((item) => !after.has(item.id)),
		both: b.filter((item) => before.has(item.id)).map((item) => [before.get(item.id) as T, item] as const),
	};
}

function plural(n: number, word: string): string {
	return `${n} ${word}${n === 1 ? '' : 's'}`;
}

function assess(
	baseline: ModelSummary,
	variant: ModelSummary,
	introduced: ArchitectureFinding[],
	resolved: ArchitectureFinding[],
): QualitativeAssessment[] {
	const out: QualitativeAssessment[] = [];
	const unitDelta = variant.deployment_units.length - baseline.deployment_units.length;
	out.push({
		dimension: 'deployment-complexity',
		basis: 'qualitative',
		statement:
			unitDelta > 0
				? `The variant adds ${plural(unitDelta, 'deployment unit')}: each is one more thing to build, deploy, monitor, secure and pay for.`
				: unitDelta < 0
					? `The variant removes ${plural(-unitDelta, 'deployment unit')}: fewer things to operate, at the cost of whatever isolation they gave.`
					: 'Both have the same deployment units.',
	});
	const syncDelta = variant.synchronous_network_connections - baseline.synchronous_network_connections;
	out.push({
		dimension: 'latency',
		basis: 'qualitative',
		statement:
			syncDelta > 0
				? `The variant has ${plural(syncDelta, 'more synchronous network call')}. Each one on a request path adds a round trip and a way to fail; how much depends on placement and region — not measured here.`
				: syncDelta < 0
					? `The variant has ${plural(-syncDelta, 'fewer synchronous network call')}, so request paths that used them have fewer round trips — not measured here.`
					: 'The number of synchronous network calls is unchanged; latency differences, if any, come from placement — not measured here.',
	});
	const addedRequirements = variant.requirements.filter((requirement) => !baseline.requirements.includes(requirement));
	out.push({
		dimension: 'operations',
		basis: 'qualitative',
		statement:
			addedRequirements.length > 0
				? `The variant needs infrastructure the baseline does not: ${addedRequirements.join(', ')}.`
				: 'No new infrastructure requirements.',
	});
	const crossingDelta = variant.trust_boundary_crossings - baseline.trust_boundary_crossings;
	const securityIntroduced = introduced.filter((entry) => entry.category === 'security').length;
	out.push({
		dimension: 'security',
		basis: 'qualitative',
		statement: `${crossingDelta === 0 ? 'Trust-boundary crossings are unchanged' : `${plural(Math.abs(crossingDelta), 'trust-boundary crossing')} ${crossingDelta > 0 ? 'added' : 'removed'}`}; ${plural(securityIntroduced, 'new security finding')}.`,
	});
	out.push({
		dimension: 'risk',
		basis: 'qualitative',
		statement:
			introduced.length === 0 && resolved.length === 0
				? 'The checks report the same findings for both.'
				: `${plural(introduced.length, 'finding')} introduced and ${plural(resolved.length, 'finding')} resolved by the variant.`,
	});
	return out;
}

export function compareArchitectures(baseline: ArchitectureModel, variant: ArchitectureModel): ArchitectureComparison {
	const a = summarize(baseline);
	const b = summarize(variant);
	const nodes = diffKeyed(baseline.nodes, variant.nodes);
	const connections = diffKeyed(baseline.connections, variant.connections);
	const zones = diffKeyed(baseline.zones, variant.zones);
	const before = new Set(a.findings.map(findingKey));
	const after = new Set(b.findings.map(findingKey));
	const introduced = b.findings.filter((entry) => !before.has(findingKey(entry)));
	const resolved = a.findings.filter((entry) => !after.has(findingKey(entry)));
	return {
		baseline: a,
		variant: b,
		...(variant.change_reason ? { change_reason: variant.change_reason } : {}),
		derived: variant.derived_from === baseline.id,
		nodes: {
			added: nodes.added,
			removed: nodes.removed,
			changed: nodes.both
				.map(([x, y]) => ({ id: y.id, label: y.label, changes: nodeChanges(x, y) }))
				.filter((change) => change.changes.length > 0),
		},
		placements: nodes.both
			.filter(([x, y]) => x.placement !== y.placement)
			.map(([x, y]) => ({ id: y.id, label: y.label, from: x.placement, to: y.placement })),
		connections: {
			added: connections.added,
			removed: connections.removed,
			changed: connections.both
				.map(([x, y]) => ({ id: y.id, label: `${y.from} → ${y.to}`, changes: connectionChanges(x, y) }))
				.filter((change) => change.changes.length > 0),
		},
		zones: { added: zones.added.map((zone) => zone.id), removed: zones.removed.map((zone) => zone.id) },
		requirements: {
			added: b.requirements.filter((requirement) => !a.requirements.includes(requirement)),
			removed: a.requirements.filter((requirement) => !b.requirements.includes(requirement)),
		},
		findings: { introduced, resolved },
		assessment: assess(a, b, introduced, resolved),
	};
}

/**
 * The decision record: one architectural question, its alternatives, the deterministic rules
 * that choose between them, the evidence behind it, and when to revisit it — the ADR/MADR
 * shape made machine-readable. `decisions.json` holds the catalogue; this file declares it and
 * parses it fail-closed.
 *
 * A decision references patterns by registry id and never copies their content: Architecture
 * Engineering says which approach fits, the pattern says how to build it. Whether every id
 * resolves is checked against the registry by `checkDecisionReferences` (called from
 * `pattern-library/validate.ts` and the unit tests).
 *
 * Hand-rolled validation, like `schema.ts`, because the stdio MCP server runs this with no
 * `node_modules`.
 */
import type { Registry } from '../schema.ts';
import {
	ENGINEERING_DOMAINS,
	type EngineeringDomain,
	EVIDENCE_KINDS,
	type EvidenceKind,
	isFactorValue,
	PLACEMENTS,
	type Placement,
	UNKNOWN,
	WORKLOAD_FACTOR_IDS,
	type WorkloadFactor,
} from './vocabulary.ts';

/** The catalogue's shape number. Bumps on a breaking change to this declaration. */
export const ARCHITECTURE_DECISION_FORMAT = 1;

export interface DecisionAlternative {
	id: string;
	approach: string;
	placement?: Placement;
	technologies: string[];
	benefits: string[];
	drawbacks: string[];
	prerequisites: string[];
	contraindications: string[];
	/** When this alternative beats the others — shown whenever it is not the one chosen. */
	prefer_when: string;
	/** Registry pattern ids that implement this alternative. */
	patterns: string[];
}

/**
 * One deterministic rule. `when` is a conjunction over factors; each factor lists the values
 * that satisfy it (a disjunction). A factor the rule does not name is irrelevant to it.
 */
export interface DecisionRule {
	id: string;
	when: Partial<Record<WorkloadFactor, string[]>>;
	choose: string;
	because: string;
}

export interface DecisionEvidence {
	kind: EvidenceKind;
	/** A repo path (optionally `#anchor`), an app route (`/showcases/wasm`) or an `https://` URL. */
	ref: string;
	claim: string;
	/** Required for `measured`: the conditions the numbers hold under. */
	conditions?: string;
	limitations: string;
}

export interface DecisionMigration {
	from: string;
	to: string;
	path: string;
	implications: string;
}

export interface ArchitectureDecision {
	id: string;
	revision: number;
	domain: EngineeringDomain;
	title: string;
	question: string;
	description: string;
	problem: {
		workload: string;
		functional: string[];
		nonfunctional: string[];
		constraints: string[];
		assumptions: string[];
	};
	alternatives: DecisionAlternative[];
	rules: DecisionRule[];
	/** The alternative chosen when no rule fires — by policy the simplest one. */
	fallback: { choose: string; because: string };
	/** Conditions under which the recommendation changes, in words. */
	changes_when: string[];
	evidence: DecisionEvidence[];
	evolution: { revisit_when: string[]; migrations: DecisionMigration[] };
	/** How conformance to the chosen alternative is checked (MADR "confirmation"), when it is. */
	confirmation?: string;
}

export interface ArchitectureDecisionCatalog {
	format: number;
	note?: string;
	decisions: ArchitectureDecision[];
}

const ID = /^[a-z0-9]+(-[a-z0-9]+)*$/;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isText(value: unknown): value is string {
	return typeof value === 'string' && value.trim().length > 0;
}

function isTextList(value: unknown): value is string[] {
	return Array.isArray(value) && value.every(isText);
}

function checkTextFields(value: Record<string, unknown>, fields: readonly string[], where: string, errors: string[]) {
	for (const field of fields) {
		if (!isText(value[field])) errors.push(`${where}.${field}: must be a non-empty string`);
	}
}

function checkListFields(value: Record<string, unknown>, fields: readonly string[], where: string, errors: string[]) {
	for (const field of fields) {
		if (!isTextList(value[field])) errors.push(`${where}.${field}: must be an array of non-empty strings`);
	}
}

function validateAlternative(value: unknown, where: string, errors: string[]): void {
	if (!isRecord(value)) {
		errors.push(`${where}: must be an object`);
		return;
	}
	checkTextFields(value, ['id', 'approach', 'prefer_when'], where, errors);
	checkListFields(
		value,
		['technologies', 'benefits', 'drawbacks', 'prerequisites', 'contraindications', 'patterns'],
		where,
		errors,
	);
	if (typeof value.id === 'string' && !ID.test(value.id)) errors.push(`${where}.id: not kebab-case`);
	if (value.placement !== undefined && !(PLACEMENTS as readonly unknown[]).includes(value.placement)) {
		errors.push(`${where}.placement: '${String(value.placement)}' is not a placement`);
	}
}

function validateRule(value: unknown, where: string, alternativeIds: Set<string>, errors: string[]): void {
	if (!isRecord(value)) {
		errors.push(`${where}: must be an object`);
		return;
	}
	checkTextFields(value, ['id', 'choose', 'because'], where, errors);
	if (typeof value.choose === 'string' && !alternativeIds.has(value.choose)) {
		errors.push(`${where}.choose: '${value.choose}' is not an alternative of this decision`);
	}
	if (!isRecord(value.when) || Object.keys(value.when).length === 0) {
		errors.push(`${where}.when: must name at least one factor`);
		return;
	}
	for (const [factor, values] of Object.entries(value.when)) {
		if (!(WORKLOAD_FACTOR_IDS as string[]).includes(factor)) {
			errors.push(`${where}.when.${factor}: not a workload factor`);
			continue;
		}
		if (!Array.isArray(values) || values.length === 0) {
			errors.push(`${where}.when.${factor}: must list at least one value`);
			continue;
		}
		for (const item of values) {
			// `unknown` is the absence of an answer, never a condition a rule may match on.
			if (item === UNKNOWN || !isFactorValue(factor as WorkloadFactor, item)) {
				errors.push(`${where}.when.${factor}: '${String(item)}' is not a value of this factor`);
			}
		}
	}
}

function validateEvidence(value: unknown, where: string, errors: string[]): void {
	if (!isRecord(value)) {
		errors.push(`${where}: must be an object`);
		return;
	}
	checkTextFields(value, ['ref', 'claim', 'limitations'], where, errors);
	if (!(EVIDENCE_KINDS as readonly unknown[]).includes(value.kind)) {
		errors.push(`${where}.kind: must be one of ${EVIDENCE_KINDS.join('|')}`);
	}
	if (value.kind === 'measured' && !isText(value.conditions)) {
		errors.push(`${where}.conditions: measured evidence must state its conditions`);
	}
	if (value.conditions !== undefined && !isText(value.conditions)) {
		errors.push(`${where}.conditions: must be a non-empty string when present`);
	}
}

function validateDecision(value: unknown, where: string, errors: string[]): void {
	if (!isRecord(value)) {
		errors.push(`${where}: must be an object`);
		return;
	}
	checkTextFields(value, ['id', 'title', 'question', 'description'], where, errors);
	checkListFields(value, ['changes_when'], where, errors);
	if (typeof value.id === 'string' && !ID.test(value.id)) errors.push(`${where}.id: not kebab-case`);
	if (!Number.isInteger(value.revision) || (value.revision as number) < 1) {
		errors.push(`${where}.revision: must be a positive integer`);
	}
	if (!(ENGINEERING_DOMAINS as readonly unknown[]).includes(value.domain)) {
		errors.push(`${where}.domain: must be one of ${ENGINEERING_DOMAINS.join('|')}`);
	}
	if (!isRecord(value.problem)) {
		errors.push(`${where}.problem: must be an object`);
	} else {
		checkTextFields(value.problem, ['workload'], `${where}.problem`, errors);
		checkListFields(
			value.problem,
			['functional', 'nonfunctional', 'constraints', 'assumptions'],
			`${where}.problem`,
			errors,
		);
	}
	const alternativeIds = new Set<string>();
	if (!Array.isArray(value.alternatives) || value.alternatives.length < 2) {
		errors.push(`${where}.alternatives: a decision needs at least two alternatives`);
	} else {
		value.alternatives.forEach((alternative, index) => {
			validateAlternative(alternative, `${where}.alternatives[${index}]`, errors);
			if (isRecord(alternative) && typeof alternative.id === 'string') {
				if (alternativeIds.has(alternative.id)) errors.push(`${where}: duplicate alternative '${alternative.id}'`);
				alternativeIds.add(alternative.id);
			}
		});
	}
	const ruleIds = new Set<string>();
	if (!Array.isArray(value.rules)) {
		errors.push(`${where}.rules: must be an array`);
	} else {
		value.rules.forEach((rule, index) => {
			validateRule(rule, `${where}.rules[${index}]`, alternativeIds, errors);
			if (isRecord(rule) && typeof rule.id === 'string') {
				if (ruleIds.has(rule.id)) errors.push(`${where}: duplicate rule '${rule.id}'`);
				ruleIds.add(rule.id);
			}
		});
	}
	if (!isRecord(value.fallback)) {
		errors.push(`${where}.fallback: must be an object`);
	} else {
		checkTextFields(value.fallback, ['choose', 'because'], `${where}.fallback`, errors);
		if (typeof value.fallback.choose === 'string' && !alternativeIds.has(value.fallback.choose)) {
			errors.push(`${where}.fallback.choose: '${value.fallback.choose}' is not an alternative`);
		}
	}
	if (!Array.isArray(value.evidence) || value.evidence.length === 0) {
		errors.push(`${where}.evidence: a decision needs at least one evidence entry`);
	} else {
		value.evidence.forEach((entry, index) => {
			validateEvidence(entry, `${where}.evidence[${index}]`, errors);
		});
	}
	if (!isRecord(value.evolution)) {
		errors.push(`${where}.evolution: must be an object`);
	} else {
		checkListFields(value.evolution, ['revisit_when'], `${where}.evolution`, errors);
		if (!Array.isArray(value.evolution.migrations)) {
			errors.push(`${where}.evolution.migrations: must be an array`);
		} else {
			value.evolution.migrations.forEach((migration, index) => {
				const at = `${where}.evolution.migrations[${index}]`;
				if (!isRecord(migration)) {
					errors.push(`${at}: must be an object`);
					return;
				}
				checkTextFields(migration, ['from', 'to', 'path', 'implications'], at, errors);
				for (const end of ['from', 'to'] as const) {
					if (typeof migration[end] === 'string' && !alternativeIds.has(migration[end])) {
						errors.push(`${at}.${end}: '${migration[end]}' is not an alternative`);
					}
				}
			});
		}
	}
	if (value.confirmation !== undefined && !isText(value.confirmation)) {
		errors.push(`${where}.confirmation: must be a non-empty string when present`);
	}
}

/** Structurally validate the parsed catalogue. Returns it typed only when there are zero errors. */
export function parseDecisionCatalog(data: unknown): {
	catalog: ArchitectureDecisionCatalog | null;
	errors: string[];
} {
	const errors: string[] = [];
	if (!isRecord(data)) return { catalog: null, errors: ['catalogue root must be an object'] };
	if (data.format !== ARCHITECTURE_DECISION_FORMAT) {
		errors.push(`format: expected ${ARCHITECTURE_DECISION_FORMAT}, got ${String(data.format)}`);
	}
	if (!Array.isArray(data.decisions) || data.decisions.length === 0) {
		errors.push('decisions: must be a non-empty array');
		return { catalog: null, errors };
	}
	const ids = new Set<string>();
	data.decisions.forEach((decision, index) => {
		validateDecision(decision, `decisions[${index}]`, errors);
		if (isRecord(decision) && typeof decision.id === 'string') {
			if (ids.has(decision.id)) errors.push(`duplicate decision id '${decision.id}'`);
			ids.add(decision.id);
		}
	});
	return errors.length > 0
		? { catalog: null, errors }
		: { catalog: data as unknown as ArchitectureDecisionCatalog, errors };
}

/** Every pattern id the catalogue names, with where it is named. */
export function decisionPatternRefs(catalog: ArchitectureDecisionCatalog): { id: string; where: string }[] {
	return catalog.decisions.flatMap((decision) =>
		decision.alternatives.flatMap((alternative) =>
			alternative.patterns.map((id) => ({ id, where: `${decision.id}/${alternative.id}` })),
		),
	);
}

/**
 * Invariant 8: every referenced pattern resolves to a canonical registry record. Returns one
 * message per dangling id; an empty list means every reference resolves.
 */
export function checkDecisionReferences(catalog: ArchitectureDecisionCatalog, registry: Registry): string[] {
	const known = new Set(registry.patterns.map((pattern) => pattern.id));
	return decisionPatternRefs(catalog)
		.filter((ref) => !known.has(ref.id))
		.map((ref) => `${ref.where}: pattern '${ref.id}' is not in the registry`);
}

import { describe, expect, it } from 'vitest';
