/**
 * The pattern dependency explorer: one deterministic projection of the registry's `depends_on`
 * graph, answered for one pattern (its prerequisites, transitively, and what builds on it) or for
 * the graph as a whole (every pattern that sits in it, grouped by category, with the hubs).
 *
 * It backs the `explore_patterns` tool, which the hosted MCP serves with an MCP Apps View
 * (`src/lib/server/mcp/apps/`). The projection is returned twice from one computation: as
 * markdown for any client, and as a JSON value the View renders — so a host without MCP Apps
 * support loses the interactivity, never the answer.
 *
 * Framework-free and filesystem-free, like `query.ts`, whose argument bounds, failure contract and
 * next-action convention it reuses.
 */

import { MAX_ARG_CHARS, type NextAction, type QueryDiag, type ToolDef, withNextActions } from './query.ts';
import type { PatternMaturity, PatternRecord, PatternRequirement, PatternTier, Registry } from './schema.ts';
import { buildById, topoSort } from './schema.ts';

export const EXPLORE_PATTERNS_TOOL_NAME = 'explore_patterns';

/** Invariants carried in the summary; the rest are counted, and `get_pattern` has them all. */
const MAX_SUMMARY_INVARIANTS = 3;
/** Hubs named in the overview: the patterns the most others build on. */
const MAX_HUBS = 5;

export const EXPLORE_PATTERNS_TOOL: ToolDef = {
	name: EXPLORE_PATTERNS_TOOL_NAME,
	description:
		"Explore the pattern library's dependency graph. With `id`: that pattern's maturity, requirements, an invariants summary, every prerequisite it builds on (depends_on, transitively, in adoption order) and every pattern that builds on it, with a docs link. Without `id`: the patterns that sit in the graph, by category, and its hubs. Read-only. Hosts that support MCP Apps render it as an interactive explorer; every other client gets the same answer as text.",
	inputSchema: {
		type: 'object',
		properties: {
			id: {
				type: 'string',
				maxLength: MAX_ARG_CHARS,
				description: 'A pattern id, e.g. "multi-client-core". Omit for the overview.',
			},
		},
		additionalProperties: false,
	},
};

/** One pattern as the explorer names it everywhere: enough to label a node and badge it. */
export interface ExploredPattern {
	id: string;
	title: string;
	category: string;
	tier: PatternTier;
	maturity: PatternMaturity;
}

/** A prerequisite in adoption order, with how many `depends_on` hops away it is. */
export interface ExploredPrerequisite {
	id: string;
	depth: number;
}

export interface ExploredFocus extends ExploredPattern {
	summary: string;
	risk: string;
	/** Own requirements and the ones inherited through a prerequisite (`via`). */
	requires: Array<{ need: PatternRequirement; via?: string }>;
	invariantCount: number;
	invariants: string[];
	/** The first contraindication, when the record names one. */
	avoidWhen: string | null;
	dependsOn: string[];
	/** Every transitive prerequisite, in adoption order (prerequisites first). */
	prerequisites: ExploredPrerequisite[];
	/** Patterns that list this one in their own `depends_on`. */
	dependents: string[];
	/** Every pattern that builds on this one, directly or through another. */
	allDependents: string[];
	/** Site path of the generated docs page (`/docs/pattern-library/<id>`); absolute when an origin was given. */
	docsUrl: string;
	cyclic: boolean;
}

export interface ExploredCategory {
	id: string;
	title: string;
	patterns: string[];
}

/** The JSON half of an answer — the View's whole input. Every id it names is in `patterns`. */
export type PatternExploration =
	| {
			kind: 'focus';
			registryVersion: string;
			focus: ExploredFocus;
			patterns: ExploredPattern[];
	  }
	| {
			kind: 'overview';
			registryVersion: string;
			categories: ExploredCategory[];
			hubs: Array<{ id: string; dependents: number }>;
			/** Registry patterns outside the graph — no prerequisite and no dependent. */
			unconnected: number;
			patterns: ExploredPattern[];
	  };

export type ExplorationOutcome =
	| { ok: true; text: string; exploration: PatternExploration }
	| { ok: false; text: string; diag: QueryDiag; next: readonly NextAction[] };

export interface ExploreOptions {
	/** The public origin the docs pages live on; without it `docsUrl` is a site path. */
	siteOrigin?: string;
}

function node(pattern: PatternRecord): ExploredPattern {
	return {
		id: pattern.id,
		title: pattern.title,
		category: pattern.category,
		tier: pattern.tier,
		maturity: pattern.maturity,
	};
}

/** `pattern id → ids that depend on it`, in registry order. */
function dependentsIndex(registry: Registry): Map<string, string[]> {
	const index = new Map<string, string[]>();
	for (const pattern of registry.patterns) {
		for (const dep of pattern.depends_on) index.set(dep, [...(index.get(dep) ?? []), pattern.id]);
	}
	return index;
}

/** Breadth-first walk from `start` (excluded) along `next`, recording the hop count. */
function walk(start: string, next: (id: string) => readonly string[]): Map<string, number> {
	const depth = new Map<string, number>();
	const queue: Array<[string, number]> = next(start).map((id) => [id, 1]);
	while (queue.length > 0) {
		const entry = queue.shift();
		if (!entry) break;
		const [id, hops] = entry;
		if (id === start || depth.has(id)) continue;
		depth.set(id, hops);
		for (const following of next(id)) queue.push([following, hops + 1]);
	}
	return depth;
}

export function patternDocsUrl(id: string, options: ExploreOptions = {}): string {
	return `${options.siteOrigin ?? ''}/docs/pattern-library/${id}`;
}

function inheritedNeeds(pattern: PatternRecord, order: string[], byId: Map<string, PatternRecord>) {
	const needs: Array<{ need: PatternRequirement; via?: string }> = pattern.requires.map((need) => ({ need }));
	for (const id of order) {
		for (const need of byId.get(id)?.requires ?? []) {
			if (!needs.some((known) => known.need === need)) needs.push({ need, via: id });
		}
	}
	return needs;
}

function focusOn(registry: Registry, pattern: PatternRecord, options: ExploreOptions): ExplorationOutcome {
	const byId = buildById(registry);
	const registryOrder = registry.patterns.map((entry) => entry.id);
	const dependents = dependentsIndex(registry);
	const upstream = walk(pattern.id, (id) => byId.get(id)?.depends_on ?? []);
	const downstream = walk(pattern.id, (id) => dependents.get(id) ?? []);
	const { order, cyclic } = topoSort([...upstream.keys()], byId, registryOrder);
	const allDependents = registryOrder.filter((id) => downstream.has(id));
	const focus: ExploredFocus = {
		...node(pattern),
		summary: pattern.summary,
		risk: pattern.risk,
		requires: inheritedNeeds(pattern, order, byId),
		invariantCount: pattern.invariants.length,
		invariants: pattern.invariants.slice(0, MAX_SUMMARY_INVARIANTS),
		avoidWhen: pattern.avoid_when[0] ?? null,
		dependsOn: [...pattern.depends_on],
		prerequisites: order.map((id) => ({ id, depth: upstream.get(id) ?? 0 })),
		dependents: [...(dependents.get(pattern.id) ?? [])],
		allDependents,
		docsUrl: patternDocsUrl(pattern.id, options),
		cyclic: cyclic || upstream.has(pattern.id) || downstream.has(pattern.id),
	};
	const named = new Set([pattern.id, ...order, ...allDependents]);
	const exploration: PatternExploration = {
		kind: 'focus',
		registryVersion: registry.version,
		focus,
		patterns: registry.patterns.filter((entry) => named.has(entry.id)).map(node),
	};
	return { ok: true, text: focusText(focus, byId), exploration };
}

function label(id: string, byId: Map<string, PatternRecord>): string {
	const pattern = byId.get(id);
	return pattern ? `\`${id}\` — ${pattern.title} (${pattern.maturity})` : `\`${id}\``;
}

function focusText(focus: ExploredFocus, byId: Map<string, PatternRecord>): string {
	const list = (ids: string[]) => (ids.length === 0 ? '- (none)' : ids.map((id) => `- ${label(id, byId)}`).join('\n'));
	const needs = focus.requires.map(({ need, via }) => (via ? `${need} (via ${via})` : need)).join(', ');
	const more = focus.invariantCount - focus.invariants.length;
	const body = [
		`# ${focus.title} (\`${focus.id}\`)`,
		`${focus.tier} · ${focus.maturity} · ${focus.category}`,
		focus.summary,
		`Requires: ${needs.length > 0 ? needs : 'nothing beyond the app runtime'}`,
		focus.avoidWhen ? `Avoid when: ${focus.avoidWhen}` : '',
		focus.invariantCount > 0
			? `## Invariants (${focus.invariantCount})\n${focus.invariants.map((line) => `- ${line}`).join('\n')}${more > 0 ? `\n- … ${more} more in get_pattern` : ''}`
			: '',
		`## Builds on (${focus.prerequisites.length}, adoption order)\n${list(focus.prerequisites.map((entry) => entry.id))}`,
		`## Built on by (${focus.dependents.length} direct, ${focus.allDependents.length} in total)\n${list(focus.allDependents)}`,
		focus.cyclic ? 'Warning: a dependency cycle touches this pattern; the order is best-effort.' : '',
		`Docs: ${focus.docsUrl}`,
	].filter((part) => part.length > 0);
	const next: NextAction[] = [
		{ tool: 'get_pattern', args: { id: focus.id }, why: 'the full card: docs, code, tests and every invariant.' },
		{
			tool: 'recommend_emulation_plan',
			args: { capabilities: [focus.title] },
			why: 'an ordered plan that includes these prerequisites.',
		},
	];
	return withNextActions(body.join('\n\n'), next);
}

function overview(registry: Registry): ExplorationOutcome {
	const dependents = dependentsIndex(registry);
	const connected = registry.patterns.filter(
		(pattern) => pattern.depends_on.length > 0 || (dependents.get(pattern.id)?.length ?? 0) > 0,
	);
	const categories: ExploredCategory[] = registry.categories
		.map((category) => ({
			id: category.id,
			title: category.title,
			patterns: connected.filter((pattern) => pattern.category === category.id).map((pattern) => pattern.id),
		}))
		.filter((category) => category.patterns.length > 0);
	const registryOrder = registry.patterns.map((pattern) => pattern.id);
	const hubs = [...dependents]
		.map(([id, ids]) => ({ id, dependents: ids.length }))
		.sort((a, b) => b.dependents - a.dependents || registryOrder.indexOf(a.id) - registryOrder.indexOf(b.id))
		.slice(0, MAX_HUBS);
	const exploration: PatternExploration = {
		kind: 'overview',
		registryVersion: registry.version,
		categories,
		hubs,
		unconnected: registry.patterns.length - connected.length,
		patterns: connected.map(node),
	};
	const body = [
		`# Pattern dependency graph (registry ${registry.version})`,
		`${connected.length} of ${registry.patterns.length} patterns build on another or are built on; ${exploration.unconnected} stand alone.`,
		`## Hubs (most built on)\n${hubs.map((hub) => `- \`${hub.id}\` — ${hub.dependents} direct dependent(s)`).join('\n')}`,
		`## By category\n${categories.map((category) => `- ${category.title}: ${category.patterns.map((id) => `\`${id}\``).join(', ')}`).join('\n')}`,
	];
	const first = hubs[0]?.id ?? registry.patterns[0]?.id ?? '';
	return {
		ok: true,
		text: withNextActions(body.join('\n\n'), [
			{
				tool: EXPLORE_PATTERNS_TOOL_NAME,
				args: { id: first },
				why: 'one pattern with its prerequisites and dependents.',
			},
		]),
		exploration,
	};
}

export function explorePatterns(
	registry: Registry,
	args: Record<string, unknown>,
	options: ExploreOptions = {},
): ExplorationOutcome {
	if (args.id === undefined) return overview(registry);
	// Bounded before use: the not-found branch echoes the id back into text and telemetry.
	if (typeof args.id !== 'string' || args.id.length === 0 || args.id.length > MAX_ARG_CHARS) {
		return {
			ok: false,
			text: `"id" must be a pattern id: a non-empty string of at most ${MAX_ARG_CHARS} characters, or omitted for the overview.`,
			diag: 'invalid_args',
			next: [{ tool: EXPLORE_PATTERNS_TOOL_NAME, why: 'the overview lists every id in the graph.' }],
		};
	}
	const pattern = registry.patterns.find((entry) => entry.id === args.id);
	if (!pattern) {
		return {
			ok: false,
			text: `No pattern with id "${args.id}".`,
			diag: 'not_found',
			next: [
				{ tool: EXPLORE_PATTERNS_TOOL_NAME, why: 'the overview lists every id in the graph.' },
				{ tool: 'search_patterns', args: { query: args.id.slice(0, 60) }, why: 'find the right id by capability.' },
			],
		};
	}
	return focusOn(registry, pattern, options);
}

files.pattern-library/schema.ts:
/**
 * The shape of the pattern library, and the rules a record must satisfy.
 *
 * Framework-free and filesystem-free on purpose: this is the ONE declaration of
 * `PatternRecord` & co. Both readers import it — the stdio server under bare Bun
 * (relative path, no bundler) and the app under Vite (via the `$patterns` alias) —
 * so the two runtimes cannot drift in their idea of what a pattern is.
 *
 * Reading the registry off disk lives in `load.ts`, which is Bun-only.
 */
export type RefKind = 'file' | 'dir' | 'route' | 'approute' | 'anchor';

/** `deep` = full emulation card (invariants + emulation notes required);
 *  `light` = index row (pointers only — both depth fields must stay empty). */
export type PatternTier = 'deep' | 'light';

/**
 * Machine-checkable evidence grade, orthogonal to tier (tier = documentation
 * depth, maturity = proof). Every value is verifiable from the record itself:
 * `proven` ⇔ at least one tests/showcases ref (whose existence patterns:validate
 * already enforces) plus a `verifiedAt`/`verifiedSha` attestation;
 * `planned` ⇔ no proof refs at all; `implemented` = code exists, no linked
 * proof surface yet. Finer self-declared rungs (unit- vs browser-verified)
 * were deliberately rejected: a grade no machine can check will rot.
 */
export type PatternMaturity = 'planned' | 'implemented' | 'proven';

/**
 * Infrastructure a pattern needs the TARGET project to have — a closed vocabulary so a
 * recommender can union it across a plan and a reader can rule a pattern out before
 * reading it. Frameworks are not listed: every pattern assumes the v10r stack's runtime.
 */
export const PATTERN_REQUIREMENTS = [
	'postgres',
	'pgvector',
	'neo4j',
	'redis',
	'object-storage',
	'cron',
	'ai-provider',
	'third-party-api',
	'web-worker',
	'wasm-toolchain',
	'service-worker',
	// A second deploy target that runs an OCI container next to the app (Podman locally,
	// a container host such as Render remotely) — for a separately deployed service.
	'container-host',
] as const;

export type PatternRequirement = (typeof PATTERN_REQUIREMENTS)[number];

/** A considered alternative and the condition under which it beats this pattern. */
export interface RegAlternative {
	approach: string;
	prefer_when: string;
}

export interface RegRef {
	path: string;
	note?: string;
	kind?: RefKind;
}

/** Meta-group for the generated Pattern Index TOC (Foundations, Data, …). */
export interface RegGroup {
	id: string;
	title: string;
}

/** Category = one generated Pattern Index section; order here IS section order. */
export interface RegCategory {
	id: string;
	title: string;
	group: string;
}

export interface PatternRecord {
	id: string;
	tier: PatternTier;
	title: string;
	category: string;
	summary: string;
	when_to_use: string;
	/**
	 * Contraindications: situations where adopting the pattern is the wrong call. The
	 * first entry is the headline the generated index prints, so keep it to one clause.
	 * Author judgement, not measurement — required on deep cards so the fitness question
	 * ("is this the smallest thing that works here?") is answered before the how.
	 */
	avoid_when: string[];
	/** Simpler or different approaches the pattern was chosen over, and when they win instead. */
	alternatives: RegAlternative[];
	/** What the target project must already run (see `PATTERN_REQUIREMENTS`). */
	requires: PatternRequirement[];
	capabilities: string[];
	keywords: string[];
	depends_on: string[];
	docs: RegRef[];
	code: RegRef[];
	tests: RegRef[];
	showcases: RegRef[];
	invariants: string[];
	emulation_notes: string[];
	risk: string;
	maturity: PatternMaturity;
	/** ISO date (YYYY-MM-DD) the proof surface was last verified. Required on `proven`, forbidden otherwise. */
	verifiedAt?: string;
	/** Short git sha of the verifying commit (`-dirty` suffix allowed, matching the perf snapshot convention). */
	verifiedSha?: string;
}

export interface Registry {
	version: string;
	note?: string;
	groups: RegGroup[];
	categories: RegCategory[];
	patterns: PatternRecord[];
}

export const REGISTRY_FILENAME = 'registry.json';

const REF_KINDS: readonly string[] = ['file', 'dir', 'route', 'approute', 'anchor'];
const TIERS: readonly string[] = ['deep', 'light'];
const MATURITIES: readonly string[] = ['planned', 'implemented', 'proven'];
const REQUIREMENTS: readonly string[] = PATTERN_REQUIREMENTS;
const VERIFIED_AT_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const ID_PATTERN = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const STRING_LIST_FIELDS = [
	'avoid_when',
	'capabilities',
	'keywords',
	'depends_on',
	'invariants',
	'emulation_notes',
] as const;
const REF_LIST_FIELDS = ['docs', 'code', 'tests', 'showcases'] as const;
const STRING_FIELDS = ['id', 'title', 'category', 'summary', 'when_to_use', 'risk'] as const;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
	return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function validateRef(value: unknown, where: string, errors: string[]): void {
	if (!isRecord(value)) {
		errors.push(`${where}: ref must be an object`);
		return;
	}
	if (typeof value.path !== 'string' || value.path.length === 0) {
		errors.push(`${where}: ref.path must be a non-empty string`);
	}
	if (value.note !== undefined && typeof value.note !== 'string') {
		errors.push(`${where}: ref.note must be a string when present`);
	}
	if (value.kind !== undefined && (typeof value.kind !== 'string' || !REF_KINDS.includes(value.kind))) {
		errors.push(`${where}: ref.kind must be one of ${REF_KINDS.join('|')}`);
	}
}

function validatePattern(value: unknown, index: number, errors: string[]): void {
	const where = `patterns[${index}]`;
	if (!isRecord(value)) {
		errors.push(`${where}: must be an object`);
		return;
	}
	for (const field of STRING_FIELDS) {
		if (typeof value[field] !== 'string' || value[field].length === 0) {
			errors.push(`${where}.${field}: must be a non-empty string`);
		}
	}
	if (typeof value.id === 'string' && !ID_PATTERN.test(value.id)) {
		errors.push(`${where}.id: '${value.id}' is not kebab-case`);
	}
	if (typeof value.tier !== 'string' || !TIERS.includes(value.tier)) {
		errors.push(`${where}.tier: must be one of ${TIERS.join('|')}`);
	}
	for (const field of STRING_LIST_FIELDS) {
		if (!isStringArray(value[field])) {
			errors.push(`${where}.${field}: must be an array of strings`);
		}
	}
	if (!Array.isArray(value.alternatives)) {
		errors.push(`${where}.alternatives: must be an array`);
	} else {
		value.alternatives.forEach((alt, altIndex) => {
			if (
				!isRecord(alt) ||
				typeof alt.approach !== 'string' ||
				alt.approach.length === 0 ||
				typeof alt.prefer_when !== 'string' ||
				alt.prefer_when.length === 0
			) {
				errors.push(`${where}.alternatives[${altIndex}]: must be {approach, prefer_when} with non-empty strings`);
			}
		});
	}
	if (!isStringArray(value.requires)) {
		errors.push(`${where}.requires: must be an array of strings`);
	} else {
		for (const requirement of value.requires) {
			if (!REQUIREMENTS.includes(requirement)) {
				errors.push(`${where}.requires: '${requirement}' is not one of ${REQUIREMENTS.join('|')}`);
			}
		}
	}
	for (const field of REF_LIST_FIELDS) {
		const list = value[field];
		if (!Array.isArray(list)) {
			errors.push(`${where}.${field}: must be an array`);
			continue;
		}
		list.forEach((ref, refIndex) => {
			validateRef(ref, `${where}.${field}[${refIndex}]`, errors);
		});
	}
	// Per-tier contract: "deep" is a promise (full emulation card), "light" a pointer
	// row. Enforced structurally so a violating registry never loads anywhere.
	if (value.tier === 'deep') {
		for (const field of ['avoid_when', 'invariants', 'emulation_notes', 'capabilities', 'keywords', 'docs'] as const) {
			if (Array.isArray(value[field]) && value[field].length === 0) {
				errors.push(`${where}.${field}: deep records must have at least one entry`);
			}
		}
	}
	if (value.tier === 'light') {
		for (const field of ['invariants', 'emulation_notes'] as const) {
			if (Array.isArray(value[field]) && value[field].length > 0) {
				errors.push(`${where}.${field}: light records must keep this empty — promote to tier "deep" instead`);
			}
		}
		if (Array.isArray(value.docs) && value.docs.length === 0) {
			errors.push(`${where}.docs: light records still need at least one docs ref`);
		}
	}
	// Maturity contract, enforced structurally (validation here is allow-extra,
	// so an unchecked field would "work" invisibly and rot):
	// proven ⇔ proof refs + attestation; planned ⇔ no proof refs; attestation
	// only on proven.
	if (typeof value.maturity !== 'string' || !MATURITIES.includes(value.maturity)) {
		errors.push(`${where}.maturity: must be one of ${MATURITIES.join('|')}`);
	} else {
		const proofRefs =
			(Array.isArray(value.tests) ? value.tests.length : 0) +
			(Array.isArray(value.showcases) ? value.showcases.length : 0);
		if (value.maturity === 'proven') {
			if (proofRefs === 0) {
				errors.push(`${where}: maturity "proven" requires at least one tests or showcases ref`);
			}
			if (typeof value.verifiedAt !== 'string' || !VERIFIED_AT_PATTERN.test(value.verifiedAt)) {
				errors.push(`${where}.verifiedAt: proven records need a YYYY-MM-DD verification date`);
			}
		} else {
			if (value.maturity === 'planned' && proofRefs > 0) {
				errors.push(
					`${where}: maturity "planned" contradicts its tests/showcases refs — use "implemented" or "proven"`,
				);
			}
			if (value.verifiedAt !== undefined || value.verifiedSha !== undefined) {
				errors.push(
					`${where}: verifiedAt/verifiedSha are attestations of "proven" — remove them or promote the maturity`,
				);
			}
		}
	}
	if (value.verifiedSha !== undefined && (typeof value.verifiedSha !== 'string' || value.verifiedSha.length === 0)) {
		errors.push(`${where}.verifiedSha: must be a non-empty string when present`);
	}
}

/** Validate the root `groups`/`categories` blocks; returns the valid category ids. */
function validateTaxonomy(data: Record<string, unknown>, errors: string[]): Set<string> {
	const groupIds = new Set<string>();
	if (!Array.isArray(data.groups) || data.groups.length === 0) {
		errors.push('groups: must be a non-empty array');
	} else {
		data.groups.forEach((group, index) => {
			if (!isRecord(group) || typeof group.id !== 'string' || !ID_PATTERN.test(group.id)) {
				errors.push(`groups[${index}].id: must be kebab-case`);
				return;
			}
			if (typeof group.title !== 'string' || group.title.length === 0) {
				errors.push(`groups[${index}].title: must be a non-empty string`);
			}
			if (groupIds.has(group.id)) {
				errors.push(`groups[${index}]: duplicate group id '${group.id}'`);
			}
			groupIds.add(group.id);
		});
	}
	const categoryIds = new Set<string>();
	if (!Array.isArray(data.categories) || data.categories.length === 0) {
		errors.push('categories: must be a non-empty array');
	} else {
		data.categories.forEach((category, index) => {
			if (!isRecord(category) || typeof category.id !== 'string' || !ID_PATTERN.test(category.id)) {
				errors.push(`categories[${index}].id: must be kebab-case`);
				return;
			}
			if (typeof category.title !== 'string' || category.title.length === 0) {
				errors.push(`categories[${index}].title: must be a non-empty string`);
			}
			if (typeof category.group !== 'string' || !groupIds.has(category.group)) {
				errors.push(`categories[${index}].group: '${String(category.group)}' is not a declared group id`);
			}
			if (categoryIds.has(category.id)) {
				errors.push(`categories[${index}]: duplicate category id '${category.id}'`);
			}
			categoryIds.add(category.id);
		});
	}
	return categoryIds;
}

/** Structurally validate parsed JSON. Returns the typed registry only when there are zero errors. */
export function parseRegistry(data: unknown): { registry: Registry | null; errors: string[] } {
	const errors: string[] = [];
	if (!isRecord(data)) {
		return { registry: null, errors: ['registry root must be an object'] };
	}
	if (typeof data.version !== 'string') {
		errors.push('version: must be a string');
	}
	const categoryIds = validateTaxonomy(data, errors);
	if (!Array.isArray(data.patterns) || data.patterns.length === 0) {
		errors.push('patterns: must be a non-empty array');
		return { registry: null, errors };
	}
	data.patterns.forEach((pattern, index) => {
		validatePattern(pattern, index, errors);
	});

	if (errors.length > 0) {
		return { registry: null, errors };
	}
	const registry = data as unknown as Registry;

	const seen = new Set<string>();
	for (const pattern of registry.patterns) {
		if (seen.has(pattern.id)) {
			errors.push(`duplicate pattern id '${pattern.id}'`);
		}
		seen.add(pattern.id);
	}
	for (const pattern of registry.patterns) {
		for (const dep of pattern.depends_on) {
			if (!seen.has(dep)) {
				errors.push(`${pattern.id}: depends_on '${dep}' does not exist`);
			}
		}
		if (!categoryIds.has(pattern.category)) {
			errors.push(`${pattern.id}: category '${pattern.category}' is not a declared category id`);
		}
	}
	return errors.length > 0 ? { registry: null, errors } : { registry, errors };
}

export function buildById(registry: Registry): Map<string, PatternRecord> {
	return new Map(registry.patterns.map((pattern) => [pattern.id, pattern]));
}

/**
 * Kahn topological sort over depends_on edges, restricted to the selected id set.
 * Deterministic: ties break by registry order. On a cycle, remaining nodes are
 * appended in registry order and `cyclic` is flagged.
 */
export function topoSort(
	selected: string[],
	byId: Map<string, PatternRecord>,
	registryOrder: string[],
): { order: string[]; cyclic: boolean } {
	const inSet = new Set(selected);
	const rank = new Map(registryOrder.map((id, index) => [id, index]));
	const byRank = (a: string, b: string) => (rank.get(a) ?? 0) - (rank.get(b) ?? 0);
	const indegree = new Map<string, number>();
	for (const id of inSet) {
		const deps = byId.get(id)?.depends_on.filter((dep) => inSet.has(dep)) ?? [];
		indegree.set(id, deps.length);
	}
	const order: string[] = [];
	let ready = [...inSet].filter((id) => indegree.get(id) === 0).sort(byRank);
	while (ready.length > 0) {
		const next = ready.shift();
		if (next === undefined) {
			break;
		}
		order.push(next);
		const unlocked: string[] = [];
		for (const id of inSet) {
			if (order.includes(id) || ready.includes(id)) {
				continue;
			}
			const deps = byId.get(id)?.depends_on.filter((dep) => inSet.has(dep)) ?? [];
			if (deps.every((dep) => order.includes(dep))) {
				unlocked.push(id);
			}
		}
		ready = [...ready, ...unlocked.filter((id) => !ready.includes(id))].sort(byRank);
	}
	const cyclic = order.length < inSet.size;
	if (cyclic) {
		const remaining = [...inSet].filter((id) => !order.includes(id)).sort(byRank);
		order.push(...remaining);
	}
	return { order, cyclic };
}

