/**
 * Offline cost model of the interface strategies an agent could use against v10r's MCP tools —
 * the evidence the decision record's Code Mode (D4) and tool-discovery (D5) revisit triggers cite.
 *
 * Deterministic and oracle-driven, like the rest of `mcp:bench`: every strategy runs the SAME
 * scripted calls (`pattern-library/bench/workflows.json`) against the real handlers, so only the
 * interface cost differs. Tokens are ceil(chars / 4) estimates; ratios are meaningful, absolute
 * counts approximate.
 *
 * Strategies, per workflow:
 *  - `direct`      every tool definition in context + each call (args, envelope) + each full result.
 *                  Run twice: with the pre-progressive calls (`baseline`) and the cheapest
 *                  progressive variant (`progressive`) — what v10r ships.
 *  - `code-mode`   the tools as generated TypeScript declarations instead of JSON schemas, one
 *                  script (generated from the calls) in one execute call, and only the FINAL
 *                  result back in context. A lower bound: an oracle script never needs to look at
 *                  an intermediate result to decide its next call, and the sandbox is free.
 *  - `discovery`   one `search_tools` meta-tool in context; each distinct tool is found by one
 *                  search returning its full definition plus two runners-up, then called directly.
 *  - `hybrid`      a rule chosen up front: `direct` while the catalogue's definitions stay under a
 *                  threshold, else `discovery` for tasks of ≤ 2 calls and `code-mode` beyond.
 *
 * What this cannot measure: model round trips actually taken, tool-selection accuracy, generated-
 * code failures, sandbox cost, latency through a real client. Those need a live evaluation lane,
 * which is a separate decision (roadmap B2).
 */

export interface ToolDefinition {
	name: string;
	description: string;
	inputSchema: Record<string, unknown>;
}

/** One executed step of a scripted workflow: the call, and the text its real handler returned. */
export interface MeasuredStep {
	tool: string;
	args: Record<string, unknown>;
	resultText: string;
}

export interface StrategyCost {
	calls: number;
	definitionTokens: number;
	callTokens: number;
	resultTokens: number;
	/** Results the model saw before the last one — the most any programmatic strategy can keep out. */
	intermediateTokens: number;
	total: number;
	/**
	 * `total` with the definitions read from a prompt cache — what a client that keeps its tool
	 * definitions in a cached prefix pays on every turn after the first. Results never are.
	 */
	totalWithCachedDefinitions: number;
}

export interface StrategyModel {
	estimateTokens(text: string): number;
	/** Per round trip, the envelope a model pays beyond the arguments. */
	callOverheadTokens: number;
}

/** Above this many definition tokens, `hybrid` stops loading every definition up front. */
export const HYBRID_DEFINITION_THRESHOLD_TOKENS = 5_000;

/**
 * Price of a cached input token relative to an uncached one. 0.1 is Anthropic's published
 * cache-read multiplier; an assumption about the client, so it is reported beside the plain total,
 * never instead of it.
 */
export const CACHED_DEFINITION_COST_RATIO = 0.1;

/** Synthetic catalogue sizes for the crossover search. 8 is the real catalogue. */
export const CATALOGUE_SCALES = [8, 32, 128, 512] as const;

/** The discovery meta-tool, as a client would define it. */
const SEARCH_TOOLS_DEFINITION: ToolDefinition = {
	name: 'search_tools',
	description:
		'Search the available tools by what you want to do. Returns the best matches with their full definitions; call a returned tool directly afterwards.',
	inputSchema: {
		type: 'object',
		properties: { query: { type: 'string', description: 'What the tool should do.' } },
		required: ['query'],
	},
};

/** The code-mode executor, as a client would define it. */
const EXECUTE_DEFINITION: ToolDefinition = {
	name: 'execute',
	description:
		'Run a TypeScript async function body against the `tools` API declared below. Only the returned value comes back.',
	inputSchema: { type: 'object', properties: { code: { type: 'string' } }, required: ['code'] },
};

function schemaToTs(schema: unknown): string {
	if (typeof schema !== 'object' || schema === null) return 'unknown';
	const node = schema as Record<string, unknown>;
	if (Array.isArray(node.enum)) return node.enum.map((value) => JSON.stringify(value)).join(' | ');
	switch (node.type) {
		case 'string':
			return 'string';
		case 'number':
		case 'integer':
			return 'number';
		case 'boolean':
			return 'boolean';
		case 'array':
			return `Array<${schemaToTs(node.items)}>`;
		case 'object': {
			const properties = (node.properties ?? {}) as Record<string, unknown>;
			const required = new Set(Array.isArray(node.required) ? (node.required as string[]) : []);
			const fields = Object.entries(properties).map(([key, value]) => {
				const description = (value as Record<string, unknown>)?.description;
				const doc = typeof description === 'string' ? `/** ${description} */ ` : '';
				return `${doc}${key}${required.has(key) ? '' : '?'}: ${schemaToTs(value)};`;
			});
			return fields.length > 0 ? `{ ${fields.join(' ')} }` : 'Record<string, unknown>';
		}
		default:
			return 'unknown';
	}
}

/** The tools as a code-mode client presents them: one typed declaration each, descriptions kept. */
export function typescriptDeclarations(tools: readonly ToolDefinition[]): string {
	const members = tools.map(
		(tool) => `\t/** ${tool.description} */\n\t${tool.name}(args: ${schemaToTs(tool.inputSchema)}): Promise<string>;`,
	);
	return `declare const tools: {\n${members.join('\n')}\n};`;
}

/** The script an oracle would write for a workflow: every call in order, the last result returned. */
export function workflowScript(steps: readonly MeasuredStep[]): string {
	const lines = steps.map((step, index) => `const r${index} = await tools.${step.tool}(${JSON.stringify(step.args)});`);
	return [...lines, `return r${steps.length - 1};`].join('\n');
}

/**
 * A synthetic catalogue of `size` tools: the real definitions cloned under distinct names, so the
 * per-tool definition cost stays realistic while the catalogue grows.
 */
export function syntheticCatalogue(tools: readonly ToolDefinition[], size: number): ToolDefinition[] {
	return Array.from({ length: size }, (_, index) => {
		const source = tools[index % tools.length];
		const copy = Math.floor(index / tools.length);
		return copy === 0
			? source
			: { ...source, name: `${source.name}_v${copy}`, description: `${source.description} (variant ${copy})` };
	});
}

function definitionsTokens(tools: readonly ToolDefinition[], model: StrategyModel): number {
	return model.estimateTokens(JSON.stringify({ tools }));
}

function direct(steps: readonly MeasuredStep[], catalogue: readonly ToolDefinition[], model: StrategyModel) {
	const results = steps.map((step) => model.estimateTokens(step.resultText));
	const callTokens = steps.reduce(
		(sum, step) => sum + model.estimateTokens(JSON.stringify(step.args)) + model.callOverheadTokens,
		0,
	);
	const resultTokens = results.reduce((sum, value) => sum + value, 0);
	const definitionTokens = definitionsTokens(catalogue, model);
	return cost(steps.length, definitionTokens, callTokens, resultTokens, resultTokens - (results.at(-1) ?? 0));
}

function codeMode(steps: readonly MeasuredStep[], catalogue: readonly ToolDefinition[], model: StrategyModel) {
	const definitionTokens =
		definitionsTokens([EXECUTE_DEFINITION], model) + model.estimateTokens(typescriptDeclarations(catalogue));
	const callTokens = model.estimateTokens(workflowScript(steps)) + model.callOverheadTokens;
	const resultTokens = model.estimateTokens(steps.at(-1)?.resultText ?? '');
	return cost(1, definitionTokens, callTokens, resultTokens, 0);
}

function discovery(steps: readonly MeasuredStep[], catalogue: readonly ToolDefinition[], model: StrategyModel) {
	const perToolDefinition = definitionsTokens(catalogue, model) / catalogue.length;
	const distinct = [...new Set(steps.map((step) => step.tool))];
	// One search per distinct tool: its own definition plus two runners-up, at the catalogue's mean size.
	const searchTokens = distinct.reduce((sum, name) => {
		const found = catalogue.find((tool) => tool.name === name);
		const own = found ? model.estimateTokens(JSON.stringify(found)) : perToolDefinition;
		return sum + own + 2 * perToolDefinition;
	}, 0);
	const searchCalls =
		distinct.length * (model.estimateTokens('{"query":"…a short task phrase…"}') + model.callOverheadTokens);
	const plain = direct(steps, [], model);
	return cost(
		steps.length + distinct.length,
		definitionsTokens([SEARCH_TOOLS_DEFINITION], model),
		plain.callTokens + searchCalls,
		plain.resultTokens + Math.round(searchTokens),
		plain.intermediateTokens + Math.round(searchTokens),
	);
}

function cost(
	calls: number,
	definitionTokens: number,
	callTokens: number,
	resultTokens: number,
	intermediateTokens: number,
): StrategyCost {
	return {
		calls,
		definitionTokens,
		callTokens,
		resultTokens,
		intermediateTokens,
		total: definitionTokens + callTokens + resultTokens,
		totalWithCachedDefinitions: Math.round(definitionTokens * CACHED_DEFINITION_COST_RATIO) + callTokens + resultTokens,
	};
}

function hybrid(steps: readonly MeasuredStep[], catalogue: readonly ToolDefinition[], model: StrategyModel) {
	if (definitionsTokens(catalogue, model) < HYBRID_DEFINITION_THRESHOLD_TOKENS)
		return { rule: 'direct', ...direct(steps, catalogue, model) };
	if (steps.length <= 2) return { rule: 'discovery', ...discovery(steps, catalogue, model) };
	return { rule: 'code-mode', ...codeMode(steps, catalogue, model) };
}

export interface MeasuredWorkflow {
	id: string;
	/** The pre-progressive calls. */
	baseline: readonly MeasuredStep[];
	/** The cheapest progressive variant's calls (what v10r ships). */
	progressive: readonly MeasuredStep[];
}

/** Every strategy for every workflow, on the real catalogue. */
export function compareStrategies(
	workflows: readonly MeasuredWorkflow[],
	tools: readonly ToolDefinition[],
	model: StrategyModel,
) {
	return workflows.map((workflow) => ({
		id: workflow.id,
		'direct-baseline': direct(workflow.baseline, tools, model),
		'direct-progressive': direct(workflow.progressive, tools, model),
		'code-mode': codeMode(workflow.progressive, tools, model),
		discovery: discovery(workflow.progressive, tools, model),
		hybrid: hybrid(workflow.progressive, tools, model),
	}));
}

/**
 * Summed cost of all workflows per strategy at each synthetic catalogue size, and the smallest
 * size at which each alternative beats shipping every definition (`direct-progressive`).
 */
export function catalogueScale(
	workflows: readonly MeasuredWorkflow[],
	tools: readonly ToolDefinition[],
	model: StrategyModel,
) {
	const rows = CATALOGUE_SCALES.map((size) => {
		const catalogue = syntheticCatalogue(tools, size);
		const sum = (strategy: typeof direct, key: 'total' | 'totalWithCachedDefinitions') =>
			workflows.reduce((total, workflow) => total + strategy(workflow.progressive, catalogue, model)[key], 0);
		const totals = (key: 'total' | 'totalWithCachedDefinitions') => ({
			'direct-progressive': sum(direct, key),
			'code-mode': sum(codeMode, key),
			discovery: sum(discovery, key),
			hybrid: sum(hybrid, key),
		});
		return {
			tools: size,
			definitionTokens: definitionsTokens(catalogue, model),
			...totals('total'),
			cachedDefinitions: totals('totalWithCachedDefinitions'),
		};
	});
	// The exact crossover, scanned tool by tool: the smallest catalogue where the alternative is
	// cheaper than shipping every definition. Equal to the real size means "already cheaper today";
	// null means "not within the scanned range".
	const firstBeating = (strategy: typeof direct, key: 'total' | 'totalWithCachedDefinitions') => {
		for (let size = tools.length; size <= CATALOGUE_SCALES[CATALOGUE_SCALES.length - 1]; size += 1) {
			const catalogue = syntheticCatalogue(tools, size);
			const total = (candidate: typeof direct) =>
				workflows.reduce((sum, workflow) => sum + candidate(workflow.progressive, catalogue, model)[key], 0);
			if (total(strategy) < total(direct)) return size;
		}
		return null;
	};
	return {
		rows,
		crossover: {
			'code-mode': firstBeating(codeMode, 'total'),
			discovery: firstBeating(discovery, 'total'),
		},
		crossoverWithCachedDefinitions: {
			'code-mode': firstBeating(codeMode, 'totalWithCachedDefinitions'),
			discovery: firstBeating(discovery, 'totalWithCachedDefinitions'),
		},
	};
}

files.scripts/patterns/build-derived.ts:
/**
 * Build (or verify) the pattern library's generated markdown surfaces from
 * `pattern-library/registry.json`:
 *
 *   - the README.md Pattern Index region (between the PATTERN-INDEX markers)
 *   - one docs page per pattern under docs/pattern-library/<id>.md (the
 *     `pattern-library` docs section — its /docs/pattern-library index page is
 *     a live route over the registry, not a generated file)
 *   - docs/pattern-library/README.md (the directory's GitHub navigation hub)
 *
 *   bun run patterns:build     # regenerate all three (commit the result)
 *   bun run patterns:check     # fail if any committed surface is stale (wired into the gate)
 *
 * Determinism: everything derives from the registry in registry order — no
 * timestamps, no environment reads — so regeneration is byte-stable and
 * `--check` reliably detects a stale surface. Orphaned pages (an id removed
 * from the registry) are deleted on build and fail `--check`, mirroring the
 * ingest script's reconcile step.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { isBlocked, parseFrontmatter } from '../../src/lib/server/docs/doc-filter.ts';
import { REGISTRY } from '../../src/lib/server/patterns/registry.ts';
import {
	PATTERN_PAGES_DIR,
	README_MARKER_END,
	README_MARKER_START,
	type RenderOpts,
	renderPatternPage,
	renderPatternsHub,
	renderReadmeIndex,
} from '../../src/lib/server/patterns/render.ts';

const ROOT = resolve(import.meta.dir, '../..');
const README_PATH = resolve(ROOT, 'README.md');
const PAGES_DIR = resolve(ROOT, PATTERN_PAGES_DIR);
const CHECK = process.argv.includes('--check');

/**
 * Same publication predicate the /docs manifest and the RAG ingester apply:
 * shared block rules from doc-filter plus the file's own frontmatter flags.
 * A path that does not exist is unpublished (renders as a code span, not a link).
 */
const opts: RenderOpts = {
	isPublishedDoc(path: string): boolean {
		if (isBlocked(path)) return false;
		const abs = resolve(ROOT, path);
		// Directories (registry `kind: "dir"` refs) are never published pages.
		if (!existsSync(abs) || !statSync(abs).isFile()) return false;
		const { frontmatter } = parseFrontmatter(readFileSync(abs, 'utf8'));
		return frontmatter.published !== false && frontmatter.draft !== true;
	},
};

interface Surface {
	/** Repo-relative label for messages. */
	label: string;
	current: string | null;
	generated: string;
	write(): void;
}

function readOrNull(path: string): string | null {
	try {
		return readFileSync(path, 'utf8');
	} catch {
		return null;
	}
}

function spliceReadme(readme: string, region: string): string {
	const start = readme.indexOf(README_MARKER_START);
	const end = readme.indexOf(README_MARKER_END);
	if (start === -1 || end === -1 || end < start) {
		console.error(
			'FAIL README.md is missing the PATTERN-INDEX markers — the generated region has nowhere to go. Restore both marker comments.',
		);
		process.exit(1);
	}
	return readme.slice(0, start) + region + readme.slice(end + README_MARKER_END.length);
}

const surfaces: Surface[] = [];

// 1. README region (whole-file compare so the splice itself is verified).
const readmeCurrent = readOrNull(README_PATH);
if (readmeCurrent === null) {
	console.error('FAIL README.md not found');
	process.exit(1);
}
const readmeGenerated = spliceReadme(readmeCurrent, renderReadmeIndex(REGISTRY));
surfaces.push({
	label: 'README.md (Pattern Index region)',
	current: readmeCurrent,
	generated: readmeGenerated,
	write: () => writeFileSync(README_PATH, readmeGenerated),
});

// 2. One page per pattern + the directory hub.
const pages = new Map<string, string>();
for (const pattern of REGISTRY.patterns) {
	pages.set(`${pattern.id}.md`, renderPatternPage(pattern, REGISTRY, opts));
}
pages.set('README.md', renderPatternsHub(REGISTRY));

for (const [name, generated] of pages) {
	const abs = resolve(PAGES_DIR, name);
	surfaces.push({
		label: `${PATTERN_PAGES_DIR}/${name}`,
		current: readOrNull(abs),
		generated,
		write: () => writeFileSync(abs, generated),
	});
}

// 3. Orphans: committed pages whose id left the registry.
const orphans = existsSync(PAGES_DIR)
	? readdirSync(PAGES_DIR).filter((name) => name.endsWith('.md') && !pages.has(name))
	: [];

const stale = surfaces.filter((surface) => surface.current !== surface.generated);

if (CHECK) {
	if (stale.length > 0 || orphans.length > 0) {
		for (const surface of stale) {
			console.error(`FAIL stale: ${surface.label}`);
		}
		for (const orphan of orphans) {
			console.error(`FAIL orphaned page: ${PATTERN_PAGES_DIR}/${orphan} (id no longer in the registry)`);
		}
		console.error('Regenerate: bun run patterns:build');
		process.exit(1);
	}
	console.error(`pattern surfaces OK: README region + ${pages.size} page(s) in sync with the registry`);
} else {
	mkdirSync(PAGES_DIR, { recursive: true });
	for (const surface of stale) {
		surface.write();
	}
	for (const orphan of orphans) {
		rmSync(resolve(PAGES_DIR, orphan));
	}
	console.error(
		`wrote ${stale.length} changed surface(s) of ${surfaces.length} (README region + ${pages.size} pages), removed ${orphans.length} orphan(s)`,
	);
}

files.scripts/perf/db-explain.ts:
#!/usr/bin/env bun
/**
 * DB performance probe — confirms the static-review findings against the real database.
 *
 * Runs read-only diagnostics (counts, EXPLAIN ANALYZE, GUC checks) so we measure
 * actual query plans + data-volume instead of guessing. Safe: every statement is a
 * SELECT / EXPLAIN / SHOW — no mutations.
 *
 * Usage (from host, via the container so env + node_modules are present):
 *   podman compose run --rm --entrypoint bun app run scripts/perf/db-explain.ts
 *
 * Targets NEON_DATABASE_URL_PROD (the real corpus). Each probe is independently
 * try/caught so one failure never aborts the rest.
 *
 * It also MEASURES `vector_query_ms`. That budget sat in budgets.json with nothing
 * producing a number for it, which is the weakest kind of budget — one that can never be
 * missed. The figure comes free: `EXPLAIN ANALYZE` already reports the executor's own
 * `Execution Time`, so scoring it costs one regex and burns neither an embedding nor an
 * extra query. The verdict is REPORTED, not enforced: this probe runs by hand against a
 * shared serverless database, and a target that fails a build because Neon was cold is a
 * target nobody keeps.
 */
import { neon } from '@neondatabase/serverless';
import { budgets, scoreBudget } from '#lib/server/perf/budgets.ts';

const url = process.env.NEON_DATABASE_URL_PROD;
if (!url) {
	console.error('NEON_DATABASE_URL_PROD is not set');
	process.exit(1);
}
const sql = neon(url);

/**
 * The query vector is a stored embedding (any chunk's), never a Gemini call. The plan
 * SHAPE would survive a synthetic vector, but the milliseconds would not: cosine
 * distance to the zero vector is NaN, which turns an HNSW walk into a random one.
 */
async function queryVector(): Promise<string> {
	const rows = (await sql.query(
		`SELECT embedding::text AS v FROM retrieval.chunk WHERE embedding IS NOT NULL LIMIT 1`,
	)) as Array<{ v: string }>;
	return rows[0]?.v ?? `[${new Array(1536).fill(0).join(',')}]`;
}

function hr(title: string) {
	console.log(`\n${'='.repeat(72)}\n${title}\n${'='.repeat(72)}`);
}

async function probe(title: string, run: () => Promise<void>) {
	hr(title);
	try {
		await run();
	} catch (e) {
		console.log(`  [skipped/failed] ${(e as Error).message}`);
	}
}

async function explain(label: string, query: string): Promise<string[]> {
	console.log(`\n--- ${label} ---`);
	const rows = (await sql.query(`EXPLAIN (ANALYZE, BUFFERS, VERBOSE) ${query}`)) as Array<Record<string, string>>;
	const plan = rows.map((r) => String(Object.values(r)[0]));
	for (const line of plan) console.log(`  ${line}`);
	return plan;
}

/** The executor's own timing, in ms. `null` when the plan did not report one. */
function executionMs(plan: string[]): number | null {
	const line = plan.find((l) => l.startsWith('Execution Time:'));
	const ms = line ? Number.parseFloat(line.replace('Execution Time:', '')) : Number.NaN;
	return Number.isFinite(ms) ? ms : null;
}

/**
 * A vector query that fell back to a sequential scan is not a slow query, it is an
 * unused index — and the difference is the whole reason this probe exists.
 */
/**
 * How the planner reached the rows. A vector-index walk is the plan the non-selective owner
 * needs; for an owner with a handful of chunks the planner rightly prefers the `user_id`
 * btree plus an in-memory sort (pgvector's iterative scan is for the middle ground), so
 * only a sequential scan is the finding.
 */
function accessPathOf(plan: string[]): 'vector index' | 'owner index + sort' | 'SEQ SCAN' {
	if (plan.some((l) => /Index Scan using .*(hnsw|embedding)/i.test(l))) return 'vector index';
	if (plan.some((l) => /Index Scan using chunk_user_idx/.test(l))) return 'owner index + sort';
	return 'SEQ SCAN';
}

const vectorMeasurements: Array<{ label: string; ms: number; path: ReturnType<typeof accessPathOf> }> = [];

await probe('CORPUS SIZE (daty P0 scaling gate)', async () => {
	const counts = (await sql.query(`
		SELECT
			(SELECT count(*) FROM retrieval.chunk) AS chunks,
			(SELECT count(*) FROM retrieval.chunk WHERE embedding IS NOT NULL) AS chunks_embedded,
			(SELECT count(*) FROM retrieval.document) AS documents,
			(SELECT count(*) FROM retrieval.document WHERE status='ready' AND deleted_at IS NULL) AS docs_ready,
			(SELECT count(DISTINCT user_id) FROM retrieval.document) AS distinct_owners
	`)) as Array<Record<string, number>>;
	console.table(counts);
	const byOwner = (await sql.query(`
		SELECT d.user_id, count(c.id) AS chunks
		FROM retrieval.chunk c JOIN retrieval.document d ON d.id = c.document_id
		GROUP BY d.user_id ORDER BY chunks DESC LIMIT 10
	`)) as Array<Record<string, unknown>>;
	console.log('Top owners by chunk count:');
	console.table(byOwner);
});

await probe('HNSW INDEX + iterative_scan GUC (daty P0)', async () => {
	const idx = (await sql.query(`
		SELECT indexname, indexdef FROM pg_indexes
		WHERE schemaname='retrieval' AND (indexdef ILIKE '%hnsw%' OR indexdef ILIKE '%ivfflat%')
	`)) as Array<Record<string, string>>;
	console.log('Vector indexes:');
	for (const r of idx) console.log(`  ${r.indexname}: ${r.indexdef}`);
	if (!idx.length) console.log('  (none found)');
	const guc = (await sql.query(`SHOW hnsw.iterative_scan`)) as Array<Record<string, string>>;
	console.log(`hnsw.iterative_scan = ${Object.values(guc[0])[0]}`);
	const ef = (await sql.query(`SHOW hnsw.ef_search`)) as Array<Record<string, string>>;
	console.log(`hnsw.ef_search = ${Object.values(ef[0])[0]}`);
});

await probe('TIER-1 VECTOR QUERY — chunk-direct form (daty P0 fix)', async () => {
	// Mirrors the rewritten retrieval/tiers/contextual.ts: filter chunk.user_id directly
	// (no JOIN), so the HNSW index is usable. Want: Index Scan, not Seq Scan + Sort.
	const owners = (await sql.query(
		`SELECT d.user_id, count(c.id) AS n FROM retrieval.chunk c JOIN retrieval.document d ON d.id=c.document_id
		 GROUP BY d.user_id ORDER BY n DESC`,
	)) as Array<{ user_id: string; n: number }>;
	const busiest = owners[0]?.user_id;
	const smallest = owners[owners.length - 1]?.user_id;
	const vec = await queryVector();
	for (const [label, owner] of [
		['busiest (non-selective)', busiest],
		['smallest (selective → tests iterative_scan)', smallest],
	] as const) {
		if (!owner) continue;
		const plan = await explain(
			`chunk-direct, owner=${label}`,
			`SELECT c.id, c.embedding <=> '${vec}'::vector AS distance
			 FROM retrieval.chunk c
			 WHERE c.user_id = '${owner}' AND c.embedding IS NOT NULL
			 ORDER BY c.embedding <=> '${vec}'::vector LIMIT 5`,
		);
		const ms = executionMs(plan);
		if (ms !== null) vectorMeasurements.push({ label, ms, path: accessPathOf(plan) });
	}
});

await probe('DESKBOT VECTOR QUERY — the source-scoped lane (retrieval/tiers/source-scope.ts)', async () => {
	// The deskbot's `desk_search_knowledge` adds a semi-join on `retrieval.document` to the
	// tier-1 shape above (`source = 'desk' AND deleted_at IS NULL`). The chatbot lane is the
	// unscoped query; this one has to keep the index walk too, or every desk search pays a
	// sequential scan the chatbot never sees.
	const owners = (await sql.query(
		`SELECT d.user_id, count(c.id) AS n FROM retrieval.chunk c JOIN retrieval.document d ON d.id=c.document_id
		 WHERE d.source = 'desk' AND d.deleted_at IS NULL GROUP BY d.user_id ORDER BY n DESC LIMIT 1`,
	)) as Array<{ user_id: string; n: number }>;
	const owner = owners[0]?.user_id;
	if (!owner) {
		console.log('  no desk documents ingested — nothing to explain');
		return;
	}
	const vec = await queryVector();
	const plan = await explain(
		'desk-scoped, busiest desk owner',
		`SELECT c.id, c.embedding <=> '${vec}'::vector AS distance
		 FROM retrieval.chunk c
		 WHERE c.user_id = '${owner}' AND c.embedding IS NOT NULL
		   AND c.document_id IN (SELECT d.id FROM retrieval.document d WHERE d.user_id = '${owner}' AND d.source = 'desk' AND d.deleted_at IS NULL)
		 ORDER BY c.embedding <=> '${vec}'::vector LIMIT 10`,
	);
	const ms = executionMs(plan);
	if (ms !== null) vectorMeasurements.push({ label: 'desk-scoped lane', ms, path: accessPathOf(plan) });
});

await probe('BLOG listPosts latest-revision read (query budget: blog.listPosts)', async () => {
	const counts = (await sql.query(`
		SELECT (SELECT count(*) FROM blog.post) AS posts,
		       (SELECT count(*) FROM blog.revision) AS revisions,
		       round((SELECT count(*) FROM blog.revision)::numeric /
		             nullif((SELECT count(*) FROM blog.post),0), 1) AS revisions_per_post
	`)) as Array<Record<string, unknown>>;
	console.table(counts);
	const ids = (await sql.query(`SELECT id FROM blog.post ORDER BY created_at DESC LIMIT 20`)) as Array<{ id: string }>;
	if (ids.length) {
		const inList = ids.map((r) => `'${r.id}'`).join(',');
		// The shape `listPosts` actually issues today. It used to read every revision of
		// every post and de-duplicate in JS — unbounded in edits × locales — so this probe
		// exists to confirm the DISTINCT ON form reaches the composite index instead of
		// sorting the whole table. `query-budget.gate.pglite.test.ts` proves the COUNT is
		// flat; only a plan can say whether the one query is cheap.
		await explain(
			'latest revision per post, DISTINCT ON over 20 ids',
			`SELECT DISTINCT ON (post_id) post_id, title, summary FROM blog.revision
			 WHERE post_id IN (${inList}) ORDER BY post_id, created_at DESC`,
		);
	}
});

hr('VECTOR QUERY BUDGET (vector_query_ms)');
if (vectorMeasurements.length === 0) {
	console.log('  no vector query completed — nothing to score');
} else {
	const budget = budgets.vector_query_ms;
	console.log(`  budget: warn >${budget.warn}ms, fail >${budget.fail}ms — ${budget.note}`);
	for (const m of vectorMeasurements) {
		const verdict = scoreBudget('vector_query_ms', m.ms);
		const path = m.path === 'SEQ SCAN' ? 'SEQ SCAN — this is the finding, not the milliseconds' : m.path;
		console.log(`  ${verdict.toUpperCase().padEnd(5)} ${m.ms.toFixed(1)}ms  ${m.label}  (${path})`);
	}
	// Reported, never enforced — see the header. A hand-run probe against a serverless
	// database that suspends after five minutes cannot own a build's exit code.
	console.log('  reported only; nothing here fails a build');
}

console.log('\nDone.\n');

