/**
 * The page-wide tracker behind center engagement (rule: `pickCenteredCard`).
 *
 * One tracker serves every latent card on the page: one passive scroll listener and one
 * resize listener, measured at most once per animation frame. It runs only while
 * `CENTER_ENGAGEMENT_QUERY` matches, so a desktop never pays for it, and it stops when
 * the last card leaves.
 */
import { CENTER_ENGAGEMENT_QUERY, pickCenteredCard } from './latent-card';

type SetCentered = (centered: boolean) => void;

const cards = new Map<HTMLElement, SetCentered>();
let current: HTMLElement | null = null;
let frame = 0;
let query: MediaQueryList | null = null;

function measure() {
	frame = 0;
	const active = query?.matches ?? false;
	const entries = [...cards.keys()];
	const index = active
		? pickCenteredCard(
				entries.map((el) => el.getBoundingClientRect()),
				window.innerHeight,
			)
		: -1;
	const next = index === -1 ? null : entries[index];
	if (next === current) return;
	if (current) cards.get(current)?.(false);
	current = next;
	if (current) cards.get(current)?.(true);
}

function schedule() {
	if (frame === 0) frame = requestAnimationFrame(measure);
}

function start() {
	query = window.matchMedia(CENTER_ENGAGEMENT_QUERY);
	query.addEventListener('change', schedule);
	window.addEventListener('scroll', schedule, { passive: true, capture: true });
	window.addEventListener('resize', schedule, { passive: true });
}

function stop() {
	query?.removeEventListener('change', schedule);
	window.removeEventListener('scroll', schedule, { capture: true });
	window.removeEventListener('resize', schedule);
	if (frame !== 0) cancelAnimationFrame(frame);
	frame = 0;
	query = null;
	current = null;
}

/** Track `card`; `setCentered` hears when it gains or loses the center. Returns the release. */
export function trackCenterEngagement(card: HTMLElement, setCentered: SetCentered): () => void {
	if (cards.size === 0) start();
	cards.set(card, setCentered);
	schedule();
	return () => {
		if (current === card) current = null;
		cards.delete(card);
		setCentered(false);
		if (cards.size === 0) stop();
		else schedule();
	};
}

import { describe, expect, it } from 'vitest';
import { isSurfaceTap, nextPinned, pickCenteredCard } from './latent-card';

describe('nextPinned', () => {
	it('toggles the pin on a surface tap', () => {
		expect(nextPinned(false, 'surface-tap')).toBe(true);
		expect(nextPinned(true, 'surface-tap')).toBe(false);
	});

	it('releases the pin on an outside tap or Escape, and never sets it', () => {
		for (const signal of ['outside-tap', 'escape'] as const) {
			expect(nextPinned(true, signal)).toBe(false);
			expect(nextPinned(false, signal)).toBe(false);
		}
	});
});

describe('isSurfaceTap', () => {
	it('counts touch and pen taps on the surface', () => {
		expect(isSurfaceTap('touch', false)).toBe(true);
		expect(isSurfaceTap('pen', false)).toBe(true);
	});

	it('ignores the mouse, which engages through hover instead', () => {
		expect(isSurfaceTap('mouse', false)).toBe(false);
	});

	it('leaves a tap on a control to the control', () => {
		expect(isSurfaceTap('touch', true)).toBe(false);
	});
});

describe('pickCenteredCard', () => {
	const viewport = 800;

	it('picks the card whose center is nearest the viewport center line', () => {
		const spans = [
			{ top: -200, bottom: 100 },
			{ top: 150, bottom: 450 },
			{ top: 500, bottom: 800 },
		];
		expect(pickCenteredCard(spans, viewport)).toBe(1);
	});

	it('moves the spotlight as the list scrolls', () => {
		const scrolled = [
			{ top: -500, bottom: -200 },
			{ top: -150, bottom: 150 },
			{ top: 200, bottom: 500 },
		];
		expect(pickCenteredCard(scrolled, viewport)).toBe(2);
	});

	it('ignores a card that only peeks in at an edge', () => {
		expect(pickCenteredCard([{ top: 700, bottom: 1100 }], viewport)).toBe(-1);
		expect(pickCenteredCard([{ top: -400, bottom: 100 }], viewport)).toBe(-1);
	});

	it('returns -1 for no cards', () => {
		expect(pickCenteredCard([], viewport)).toBe(-1);
	});
});

/**
 * Latent Card — the engagement model.
 *
 * A latent card has two looks and one capability: at rest its actions are neutral, when
 * the card is *engaged* they take their colour. Engagement changes emphasis, never what
 * the user can do — a resting action is a real, enabled control.
 *
 * Hover and keyboard focus engage the card through CSS (`:hover` under `(hover: hover)`,
 * `:focus-within`), so they work before hydration and need no state. The one signal CSS
 * cannot express is a touch tap on the card's surface, which pins the card engaged until
 * the user dismisses it. That pin is the only state, and this module is its rule.
 */

/** One action a latent card offers. Rendered as a `Button`; never disabled at rest. */
export interface LatentCardAction {
	/** Stable key within the card. */
	id: string;
	/** Visible text, and the accessible name of an icon-only action. */
	label: string;
	/** UnoCSS icon class, e.g. `i-lucide-share-2`. */
	icon?: string;
	/** Renders the action as a link. */
	href?: string;
	onSelect?: () => void;
	/** The colour the action takes when the card is engaged. */
	tone?: LatentActionTone;
}

/** `primary` marks the card's main action; `danger` a destructive one. */
export type LatentActionTone = 'neutral' | 'primary' | 'danger';

/**
 * Where the actions sit: a `footer` bar with labels, or a `corner` cluster of icon-only
 * actions in the header (labels become the accessible name and tooltip).
 */
export type LatentActionPlacement = 'footer' | 'corner';

/**
 * What can change the touch pin.
 * - `surface-tap`: a touch or pen tap on the card outside any interactive control
 * - `outside-tap`: a pointer down anywhere outside the card
 * - `escape`: the Escape key inside the card
 */
export type LatentCardSignal = 'surface-tap' | 'outside-tap' | 'escape';

/** The next pin after `signal`. A surface tap toggles; anything else releases. */
export function nextPinned(pinned: boolean, signal: LatentCardSignal): boolean {
	if (signal === 'surface-tap') return !pinned;
	return false;
}

/**
 * Whether a pointer down counts as a surface tap. Only touch and pen pin: a mouse
 * already engages the card through hover, and pinning it too would leave the card
 * engaged after the pointer leaves. A tap that lands on a control belongs to that
 * control and leaves the pin alone.
 */
export function isSurfaceTap(pointerType: string, onInteractiveControl: boolean): boolean {
	return (pointerType === 'touch' || pointerType === 'pen') && !onInteractiveControl;
}

/** Elements whose taps belong to themselves, not to the card's surface. */
export const INTERACTIVE_SELECTOR =
	'a[href], button, input, select, textarea, summary, [role="button"], [role="tab"], [role="slider"], [contenteditable="true"], [tabindex]:not([tabindex="-1"])';

/**
 * Center engagement — where hover does not exist, scrolling engages instead.
 *
 * On a touch screen there is no hover to say which card the user is reaching for, but
 * the card they are reading sits near the middle of the screen. Among the cards on
 * screen, the one whose center is nearest the viewport's center line is engaged; the
 * rest stay latent. Only one card is centered at a time, so a scrolling list reads as a
 * single spotlight moving down the page.
 */
export interface CardSpan {
	top: number;
	bottom: number;
}

/**
 * Index of the centered card, or -1 when none qualifies. A card qualifies when its own
 * center is on screen (between 0 and `viewportHeight`), so a card that only peeks in at
 * an edge never steals the spotlight.
 */
export function pickCenteredCard(spans: readonly CardSpan[], viewportHeight: number): number {
	const line = viewportHeight / 2;
	let best = -1;
	let bestDistance = Number.POSITIVE_INFINITY;
	spans.forEach((span, i) => {
		const center = (span.top + span.bottom) / 2;
		if (center < 0 || center > viewportHeight) return;
		const distance = Math.abs(center - line);
		if (distance < bestDistance) {
			best = i;
			bestDistance = distance;
		}
	});
	return best;
}

/** The media query under which center engagement runs: no hover, coarse pointer. */
export const CENTER_ENGAGEMENT_QUERY = '(hover: none) and (pointer: coarse)';

