				writer: { merge: () => void; write: (frame: Record<string, unknown>) => void };
			}) => Promise<void>;
			onError?: (error: unknown) => string;
		}) => {
			streamRun.writes = [];
			streamRun.done = execute({
				writer: {
					merge: vi.fn(),
					write: (frame) => {
						streamRun.writes.push(frame);
						streamRun.onWrite?.(frame);
