/**
 * The approval replay against a real database: a step's mutation and its receipt commit
 * together, the plan stops at the first step that is not `ok` with the earlier steps
 * kept, a step that already has a receipt is never run again, and the deterministic
 * receipt message lands in the conversation.
 */
import type { PGlite } from '@electric-sql/pglite';
import { eq } from 'drizzle-orm';
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest';
import { makeConversation, makeUser } from '#lib/server/test/fixtures.ts';
import { conversation, message } from '../../db/schema/ai/conversation';
import { agentProposal } from '../../db/schema/ai/proposal';
import { user } from '../../db/schema/auth/_better-auth';
import { file } from '../../db/schema/desk';

let testClient: PGlite;

vi.mock('#lib/server/db/index.ts', async () => {
	const { createTestDb } = await import('#lib/server/test/db.ts');
	const { db, client } = await createTestDb();
	testClient = client;
	return { db };
});

/** The real receipt writer, with one seam: a test can make the next call throw. */
let failNextReceipt = false;
vi.mock('#lib/server/db/ai/proposals.ts', async (importOriginal) => {
	const actual = await importOriginal<typeof import('#lib/server/db/ai/proposals.ts')>();
	return {
		...actual,
		recordProposalStep: async (...args: Parameters<typeof actual.recordProposalStep>) => {
			if (failNextReceipt) {
				failNextReceipt = false;
				throw new Error('receipt write refused');
			}
			return actual.recordProposalStep(...args);
		},
	};
});

const { executeProposal, receiptText } = await import('./execute-proposal');
const { proposalOutcome } = await import('./proposal-outcome');
const { approveProposal, createProposal, getProposal, listProposalSteps, markExecuting, recordProposalStep } =
	await import('#lib/server/db/ai/proposals.ts');
const { createSpreadsheetFile, updateSpreadsheetByFileId } = await import('#lib/server/db/desk/mutations.ts');
const { getFile, getSpreadsheetByFileId, listFiles } = await import('#lib/server/db/desk/queries.ts');
const { readProposedTarget } = await import('../tools/proposed-target');
const { db } = await import('#lib/server/db/index.ts');

const USER = makeUser({ id: 'user-replay' });
let conversationId: string;
let messageId: string;

async function claimed(payload: Parameters<typeof createProposal>[0]['payload']) {
	const proposal = await createProposal({
		conversationId,
		messageId,
		payload,
		grantedScopes: ['desk:read', 'desk:write', 'desk:create', 'desk:delete'],
	});
	await approveProposal(proposal.id, USER.id);
	const row = await markExecuting(proposal.id);
	if (!row) throw new Error('claim failed');
	return row;
}

describe('executeProposal', () => {
	beforeAll(async () => {
		await db.insert(user).values(USER);
		const conv = makeConversation({ userId: USER.id, id: crypto.randomUUID() });
		await db.insert(conversation).values(conv);
		conversationId = conv.id;
		messageId = crypto.randomUUID();
		await db.insert(message).values({ id: messageId, conversationId, role: 'assistant', content: '' });
	});
	afterAll(async () => {
		await testClient?.close();
	});

	it('runs every step, writes one receipt per step and a receipt message the model can read', async () => {
		const { file: sheet } = await createSpreadsheetFile(USER.id, 'Budget', { A1: { v: 1 } });
		const target = await readProposedTarget(USER.id, sheet.id);
		const proposal = await claimed([
			{ toolName: 'desk_create_markdown', args: { name: 'Notes', content: '# hi' }, action: 'Create "Notes"' },
			{
				toolName: 'desk_update_cells',
				args: { file_id: sheet.id, updates: [{ cell: 'A1', value: 2 }] },
				action: 'Set A1 to 2 in "Budget"',
				target: target ?? undefined,
			},
		]);

		const outcome = await executeProposal(proposal, USER.id);

		expect(outcome.status).toBe('executed');
		expect(outcome.steps.map((s) => s.kind)).toEqual(['ok', 'ok']);
		expect(outcome.effects.map((e) => e.type)).toEqual([
			'desk:refresh_explorer',
			'desk:open_panel',
			'desk:tab_indicator',
			'desk:refresh_file',
			'desk:tab_indicator',
		]);
		expect((await getProposal(proposal.id))?.status).toBe('executed');

		const receipts = await listProposalSteps(proposal.id);
		expect(receipts.map((r) => r.stepIndex)).toEqual([0, 1]);
		expect(receipts[0]?.createdFileId).toBeTruthy();

		expect(outcome.receiptMessage?.text).toContain('Ran the approved plan (2 of 2 steps).');
		expect(outcome.receiptMessage?.text).toContain('2. Set A1 to 2 in "Budget" — done (now version 1)');
		const [saved] = await db
			.select()
			.from(message)
			.where(eq(message.id, outcome.receiptMessage?.id ?? ''));
		expect(saved).toMatchObject({ role: 'assistant', conversationId, content: outcome.receiptMessage?.text });
	});

	it('stops at the first step that is not ok and keeps what ran; a conflict is named as one', async () => {
		const { file: sheet } = await createSpreadsheetFile(USER.id, 'Moving', { A1: { v: 1 } });
		const target = await readProposedTarget(USER.id, sheet.id);
		// The user saves between review and approval.
		await updateSpreadsheetByFileId(sheet.id, USER.id, { cells: { A1: { v: 9 } }, expectedVersion: 0 });

		const proposal = await claimed([
			{ toolName: 'desk_create_markdown', args: { name: 'Before', content: 'x' }, action: 'Create "Before"' },
			{
				toolName: 'desk_update_cells',
				args: { file_id: sheet.id, updates: [{ cell: 'B1', value: 'late' }] },
				action: 'Write B1',
				target: target ?? undefined,
			},
			{ toolName: 'desk_create_markdown', args: { name: 'Never', content: 'x' }, action: 'Create "Never"' },
		]);

		const outcome = await executeProposal(proposal, USER.id);

		expect(outcome.status).toBe('failed');
		expect(outcome.failureMessage).toBe('conflict');
		expect(outcome.steps.map((s) => s.kind)).toEqual(['ok', 'conflict']);
		const names = (await listFiles(USER.id)).items.map((f) => f.name);
		expect(names).toContain('Before');
		expect(names).not.toContain('Never');
		expect(outcome.receiptMessage?.text).toContain('stopped after 1 of 3 steps');
		expect(outcome.receiptMessage?.text).toContain('3. Create "Never" — not run');
		expect((await getProposal(proposal.id))?.failureMessage).toBe('conflict');
	});

	it('rolls a step back when its receipt cannot be written — no mutation without a receipt', async () => {
		const { file: sheet } = await createSpreadsheetFile(USER.id, 'Guarded', { A1: { v: 1 } });
		const target = await readProposedTarget(USER.id, sheet.id);
		const proposal = await claimed([
			{
				toolName: 'desk_rename_file',
				args: { file_id: sheet.id, name: 'Renamed' },
				action: 'Rename',
				target: target ?? undefined,
			},
		]);

		failNextReceipt = true;
		const outcome = await executeProposal(proposal, USER.id);

		expect(outcome.status).toBe('failed');
		expect(outcome.steps).toEqual([]);
		expect((await getFile(sheet.id, USER.id))?.name).toBe('Guarded');
	});

	it('never runs a step that already has a receipt — a create is not minted twice', async () => {
		const proposal = await claimed([
			{ toolName: 'desk_create_markdown', args: { name: 'Once', content: 'x' }, action: 'Create "Once"' },
		]);
		// An earlier execution ran the step and died before its terminal transition.
		await recordProposalStep(db, {
			proposalId: proposal.id,
			stepIndex: 0,
			toolName: 'desk_create_markdown',
			kind: 'ok',
			output: { created: true, fileId: 'fil_earlier', name: 'Once' },
			createdFileId: 'fil_earlier',
		});

		const outcome = await executeProposal(proposal, USER.id);

		expect(outcome.status).toBe('executed');
		expect(outcome.steps).toHaveLength(1);
		const created = await db.select().from(file).where(eq(file.name, 'Once'));
		expect(created).toHaveLength(0);
	});

	it('rebuilds the outcome of a settled proposal from its receipts', async () => {
		const proposal = await claimed([
			{ toolName: 'desk_create_markdown', args: { name: 'Settled', content: 'x' }, action: 'Create "Settled"' },
		]);
		const live = await executeProposal(proposal, USER.id);
		const later = await proposalOutcome((await getProposal(proposal.id)) ?? proposal);

		expect(later.status).toBe('executed');
		expect(later.steps).toEqual(live.steps);
		expect(later.effects).toEqual(live.effects);
		expect(later.receiptMessage).toBeNull();
	});

	it('writes the receipt text deterministically from the receipts', () => {
		const proposal = {
			payload: [
				{ toolName: 'desk_rename_file', args: {}, action: 'Rename "a" → "b"' },
				{ toolName: 'desk_delete_file', args: {}, action: 'Delete "c"' },
			],
		} as unknown as Parameters<typeof receiptText>[0];
		const text = receiptText(
			proposal,
			[{ stepIndex: 0, toolName: 'desk_rename_file', kind: 'failed', output: null, errorMessage: 'File not found.' }],
			'failed',
		);
		expect(text).toBe(
			[
				'The approved plan stopped after 0 of 2 steps; nothing was rolled back.',
				'1. Rename "a" → "b" — failed: File not found.',
				'2. Delete "c" — not run',
			].join('\n'),
		);
	});
	// The lease heals a stalled run to failed('interrupted'); the fence makes that terminal.
	// Without it, the stalled executor's next step would still commit behind the status.
	it('commits no further step once the run was healed to interrupted', async () => {
		const { file: sheet } = await createSpreadsheetFile(USER.id, 'Fenced', { A1: { v: 1 } });
		const target = await readProposedTarget(USER.id, sheet.id);
		const row = await claimed([
			{
				toolName: 'desk_update_cells',
				args: { file_id: sheet.id, updates: [{ cell: 'A1', value: 2 }] },
				action: 'Set A1 to 2 in "Fenced"',
				target: target ?? undefined,
			},
		]);
		await db
			.update(agentProposal)
			.set({ status: 'failed', failureMessage: 'interrupted' })
			.where(eq(agentProposal.id, row.id));

		const outcome = await executeProposal(row, USER.id);

		expect(outcome.status).toBe('failed');
		expect(outcome.failureMessage).toBe('interrupted');
		expect(await listProposalSteps(row.id)).toEqual([]);
		expect((await getProposal(row.id))?.failureMessage).toBe('interrupted');
		// The fenced step's mutation rolled back with it.
		expect((await getSpreadsheetByFileId(sheet.id, USER.id))?.spreadsheet.cells.A1?.v).toBe(1);
	});
});

/**
 * Runs an approved proposal — the business half of `POST /api/ai/proposals/[id]/approve`.
 *
 * Each step's desk mutation and its receipt (`agent_proposal_step`) commit in ONE
 * transaction, so after any crash the receipts are exactly the set of mutations that
 * happened; the receipts' primary key refuses a second execution of a step. The plan is a
 * sequence, not a batch: it stops at the first step that is not `ok` and the earlier
 * steps stay — there is no rollback, and the receipts say so.
 *
 * What the user reads afterwards is deterministic: the receipt message is written here,
 * from the receipts, as an assistant row of the conversation. The desk client shows it
 * under the card and carries it in the history it sends, so the model learns what ran the
 * same way it learns everything else — no acknowledgement model call, nothing to fall
 * through into a mutating turn if the plan failed.
 */

import { saveMessages } from '#lib/server/db/ai/mutations.ts';
import {
	listProposalSteps,
	lockExecuting,
	markExecuted,
	markFailed,
	recordProposalStep,
	touchExecuting,
} from '#lib/server/db/ai/proposals.ts';
import { db } from '#lib/server/db/index.ts';
import type { agentProposal } from '#lib/server/db/schema/ai/proposal.ts';
import type { ProposalOutcome, ProposalReceiptMessage, ProposalStepReceipt } from '#lib/types/ai-proposal.ts';
import type { ProposalStatus } from '#lib/types/db-enums.ts';
import type { DeskToolScope } from '../tools/_types';
import { executeDeskToolCall } from '../tools/desk-execute';
import { effectsOfReceipts, toStepReceipt } from './proposal-outcome';

type ProposalRow = typeof agentProposal.$inferSelect;

/**
 * The terminal reason the client tells apart from a step's own error text. Its sibling,
 * `'interrupted'`, is written by `markInterruptedIfStale` when a run outlives its lease.
 */
const FAILURE_CONFLICT = 'conflict';

/** Same reason the healer writes: this run lost its lease, and the fence stopped its next step. */
const FAILURE_FENCED = 'interrupted';

/**
 * The deterministic account of a run: one line per planned step — done, failed, or never
 * reached. Plain prose, because it is stored as an assistant message and read by both the
 * user and the model.
 */
export function receiptText(
	proposal: ProposalRow,
	steps: readonly ProposalStepReceipt[],
	status: ProposalStatus,
): string {
	const byIndex = new Map(steps.map((s) => [s.stepIndex, s]));
	const done = steps.filter((s) => s.kind === 'ok').length;
	const total = proposal.payload.length;
	const head =
		status === 'executed'
			? `Ran the approved plan (${done} of ${total} step${total === 1 ? '' : 's'}).`
			: `The approved plan stopped after ${done} of ${total} step${total === 1 ? '' : 's'}; nothing was rolled back.`;
	const lines = proposal.payload.map((step, index) => {
		const receipt = byIndex.get(index);
		const label = `${index + 1}. ${step.action}`;
		if (!receipt) return `${label} — not run`;
		if (receipt.kind === 'ok') {
			const version =
				receipt.output && typeof receipt.output.version === 'number' ? ` (now version ${receipt.output.version})` : '';
			return `${label} — done${version}`;
		}
		return `${label} — ${receipt.kind === 'conflict' ? 'conflict: ' : 'failed: '}${receipt.errorMessage ?? 'unknown error'}`;
	});
	return [head, ...lines].join('\n');
}

/**
 * Execute the payload of a proposal already in `executing`. Returns the outcome the
 * client renders; never throws for a step's failure — that is a receipt, not an error.
 */
export async function executeProposal(proposal: ProposalRow, userId: string): Promise<ProposalOutcome> {
	const scopes = (proposal.grantedScopes ?? []) as DeskToolScope[];
	const steps: ProposalStepReceipt[] = (await listProposalSteps(proposal.id)).map(toStepReceipt);
	let failure: string | null = null;

	for (const [index, step] of proposal.payload.entries()) {
		// A receipt already present means this step ran in an execution that lost its
		// terminal transition; it is not run twice.
		if (steps.some((s) => s.stepIndex === index)) continue;

		let receipt: ProposalStepReceipt;
		try {
			receipt = await db.transaction(async (tx) => {
				// The fence: a run healed to failed('interrupted') while this one stalled must not
				// commit another step behind the terminal status.
				if (!(await lockExecuting(tx, proposal.id))) throw new Error(FAILURE_FENCED);
				// Replay under the scopes frozen when the plan was PROPOSED, never anything
				// supplied on the approving request — approval must not widen the reviewed grant.
				const outcome = await executeDeskToolCall(
					{ userId, scopes, handle: tx },
					step.toolName,
					step.args,
					step.target,
				);
				const row = await recordProposalStep(tx, {
					proposalId: proposal.id,
					stepIndex: index,
					toolName: step.toolName,
					kind: outcome.ok ? 'ok' : outcome.kind,
					output: outcome.ok ? outcome.output : null,
					errorMessage: outcome.ok ? undefined : outcome.errorMessage,
					createdFileId:
						outcome.ok && outcome.output.created === true && typeof outcome.output.fileId === 'string'
							? outcome.output.fileId
							: undefined,
					recovery: outcome.ok ? outcome.recovery : undefined,
				});
				return toStepReceipt(row);
			});
		} catch (err) {
			// The receipt could not be written, so the mutation rolled back with it. A primary
			// key collision here means another execution already owns this step.
			failure = err instanceof Error ? err.message : 'Step could not be recorded.';
			break;
		}

		steps.push(receipt);
		if (receipt.kind !== 'ok') {
			failure = receipt.kind === 'conflict' ? FAILURE_CONFLICT : (receipt.errorMessage ?? 'Step failed.');
			break;
		}
		await touchExecuting(proposal.id);
	}

	const status: ProposalStatus = failure === null ? 'executed' : 'failed';
	if (failure === null) await markExecuted(proposal.id);
	else await markFailed(proposal.id, failure);

	const receiptMessage = await persistReceiptMessage(proposal, userId, steps, status);
	return {
		id: proposal.id,
		status,
		steps,
		failureMessage: failure,
		effects: effectsOfReceipts(steps),
		receiptMessage,
		expiresAt: proposal.expiresAt.toISOString(),
		revert: null,
	};
}

async function persistReceiptMessage(
	proposal: ProposalRow,
	userId: string,
	steps: readonly ProposalStepReceipt[],
	status: ProposalStatus,
): Promise<ProposalReceiptMessage | null> {
	const text = receiptText(proposal, steps, status);
	const id = crypto.randomUUID();
	try {
		await saveMessages(proposal.conversationId, userId, [{ id, role: 'assistant', content: text }]);
		return { id, text };
	} catch (err) {
		// The receipts already hold the truth; a lost message only costs the transcript a line.
		console.error('[ai:proposal] Failed to persist the receipt message:', err);
		return null;
	}
}

