 * shapes stay here.
 */

export type {
	DeskEffect,
	DeskToolMeta,
	DeskToolScope,
	ToolDescriptor,
	ToolMeta,
	ToolRisk,
} from '#lib/types/ai-tools.ts';
export { DESK_TOOL_SCOPES } from '#lib/types/ai-tools.ts';

