import { describe, expect, it } from 'vitest';
import { MAX_OBSERVED_SHAPES, observeQuery, queryCensusLogger, queryShape, startQueryCensus } from './query-census';

describe('queryShape', () => {
	it('treats parameter lists of any length as one shape', () => {
		const three = queryShape('select * from post where id in ($1, $2, $3)');
		const thirty = queryShape(
			`select * from post where id in (${Array.from({ length: 30 }, (_, i) => `$${i + 1}`).join(', ')})`,
		);

		// Batching is the FIX for what this measures; a normalizer that told batch
		// sizes apart would report every batch as a brand-new shape.
		expect(three).toBe(thirty);
	});

	it('keeps genuinely different statements apart', () => {
		expect(queryShape('select id from post where slug = $1')).not.toBe(
			queryShape('select id from tag where slug = $1'),
		);
	});

	it('normalizes whitespace, literals and numbers', () => {
		expect(queryShape("select  *\n\tfrom post\nwhere status = 'draft' limit 25")).toBe(
			"select * from post where status = '?' limit N",
		);
	});

	it('bounds the stored shape', () => {
		expect(queryShape(`select ${'a'.repeat(5000)} from post`).length).toBeLessThanOrEqual(300);
	});
});

describe('query census', () => {
	it('counts nothing when no census is in scope', () => {
		// The cost outside a scope is one AsyncLocalStorage lookup, which is what makes
		// it acceptable to leave the driver's logger wired up permanently.
		expect(() => observeQuery('select 1')).not.toThrow();
	});

	it('counts every statement sent inside its scope, at any async depth', async () => {
		const census = startQueryCensus();

		await census.run(async () => {
			observeQuery('select 1');
			await Promise.resolve();
			await new Promise((resolve) => setTimeout(resolve, 1));
			observeQuery('select 2');
		});

		expect(census.count).toBe(2);
	});

	it('does not count statements sent outside its scope', async () => {
		const census = startQueryCensus();
		await census.run(async () => observeQuery('select 1'));
		observeQuery('select 2');

		expect(census.count).toBe(1);
	});

	it('reports the most repeated shape', () => {
		const census = startQueryCensus();

		census.run(() => {
			observeQuery('select * from file where id = $1');
			observeQuery('select * from file where id = $2');
			observeQuery('select * from file where id = $3');
			observeQuery('select count(*) from file');
		});

		expect(census.count).toBe(4);
		expect(census.worst()).toEqual({ shape: 'select * from file where id = $?', times: 3 });
	});

	it('calls a single occurrence no repeat at all', () => {
		const census = startQueryCensus();
		census.run(() => observeQuery('select 1'));

		expect(census.worst()).toBeNull();
	});

	it('keeps counting truthfully after it stops recording shapes', () => {
		const census = startQueryCensus();

		census.run(() => {
			for (let i = 0; i < MAX_OBSERVED_SHAPES + 10; i++) observeQuery(`select ${'x'.repeat(i)} from post`);
		});

		// The count is the number people act on; the shape list is a diagnostic. Dropping
		// the diagnostic under pathological variety is fine, silently under-counting is not.
		expect(census.count).toBe(MAX_OBSERVED_SHAPES + 10);
		expect(census.repeats().length).toBe(MAX_OBSERVED_SHAPES);
	});

	it('counts through the driver seam the app actually wires up', () => {
		const census = startQueryCensus();
		census.run(() => queryCensusLogger.logQuery('select 1 from post', []));

		expect(census.count).toBe(1);
	});
});

files.src/lib/server/db/query-census.ts:
/**
 * Query census — how many times one request went to the database, and how many of
 * those were the same question asked again.
 *
 * Latency work stalls at "the page is slow" until the round trips are countable.
 * A census is the counting half: it observes every statement Drizzle sends inside a
 * scope and reports the total plus the repeated shapes. It deliberately does NOT
 * time individual statements — Drizzle's `Logger` fires before execution and carries
 * no duration, and a wrapper around the driver would buy a wall clock around a
 * network call when `EXPLAIN ANALYZE` already answers "why is this query slow"
 * better. The question this answers is the one the driver can answer honestly:
 * *how many times did we ask?*
 *
 * Two things are load-bearing.
 *
 *   Free when nobody is counting. Outside a scope `observeQuery` is one
 *   `AsyncLocalStorage.getStore()` and a return. Drizzle has already built the SQL
 *   string it hands us, so nothing is serialized for the census's benefit.
 *
 *   A repeat is a suspicion, not a verdict. Two identical statements may be two
 *   legitimate lookups. N+1 is not "this shape repeated" — it is "the count grows
 *   with the row count", and a single request cannot see that: it has one row count.
 *   The runtime census reports the suspicion; `query-budget.gate.pglite.test.ts`
 *   proves the scaling by running the same operation over two data sizes. Do not
 *   promote the heuristic into an assertion here.
 */

import { AsyncLocalStorage } from 'node:async_hooks';
import type { Logger } from 'drizzle-orm';

/** A statement shape and how many times it was sent. */
export interface RepeatedShape {
	shape: string;
	times: number;
}

/**
 * Ceiling on DISTINCT shapes retained. Reached only by a request that generates
 * unbounded query variety — which is the bug, not the budget — so overflow stops
 * recording shapes while `count` keeps counting truthfully.
 */
export const MAX_OBSERVED_SHAPES = 128;

/** Statement shapes are stored, compared and printed; an unbounded one is a memory leak in a log line. */
const MAX_SHAPE_CHARS = 300;

/**
 * Reduce a statement to its shape, so the same question asked about different rows
 * counts as one shape.
 *
 * The parameter-list collapse is the rule that matters: `id IN ($1, $2, $3)` and
 * `id IN ($1, $2, ..., $30)` are one batched read, and a normalizer that told them
 * apart would report every batch as a new shape — which is precisely backwards,
 * since batching is the fix for the thing this measures.
 */
export function queryShape(statement: string): string {
	return statement
		.replace(/\s+/g, ' ')
		.replace(/'[^']*'/g, "'?'")
		.replace(/\$\d+(?:\s*,\s*\$\d+)+/g, '$…')
		.replace(/\$\d+/g, '$?')
		.replace(/\b\d+\b/g, 'N')
		.trim()
		.slice(0, MAX_SHAPE_CHARS);
}

export interface QueryCensus {
	/** Round trips observed, including any whose shape was dropped past the cap. */
	readonly count: number;
	/** Distinct shapes with their send counts, most repeated first. */
	repeats(): RepeatedShape[];
	/** The most repeated shape, or `null` when nothing was sent twice. */
	worst(): RepeatedShape | null;
	/** Run `work` with this census collecting every query made inside it, at any depth. */
	run<T>(work: () => T): T;
}

interface CensusRecorder {
	total: number;
	shapes: Map<string, number>;
}

const scope = new AsyncLocalStorage<CensusRecorder>();

function viewOf(recorder: CensusRecorder): QueryCensus {
	const repeats = (): RepeatedShape[] =>
		[...recorder.shapes.entries()].map(([shape, times]) => ({ shape, times })).sort((a, b) => b.times - a.times);

	return {
		get count() {
			return recorder.total;
		},
		repeats,
		worst() {
			const [first] = repeats();
			return first && first.times > 1 ? first : null;
		},
		run: (work) => scope.run(recorder, work),
	};
}

export function startQueryCensus(): QueryCensus {
	return viewOf({ total: 0, shapes: new Map() });
}

/** Round trips the census in scope has seen so far — undefined when nobody is counting. */
export function observedQueryCount(): number | undefined {
	return scope.getStore()?.total;
}

/** Record one round trip against the census in scope. A no-op when nobody is counting. */
export function observeQuery(statement: string): void {
	const recorder = scope.getStore();
	if (!recorder) return;

	recorder.total += 1;
	const shape = queryShape(statement);
	const seen = recorder.shapes.get(shape);
	if (seen === undefined && recorder.shapes.size >= MAX_OBSERVED_SHAPES) return;
	recorder.shapes.set(shape, (seen ?? 0) + 1);
}

/**
 * The Drizzle seam. Passed as the driver's `logger`, which is why nothing else in the
 * codebase has to remember to call `observeQuery` — every statement any domain sends
 * goes through here, including the ones inside Better Auth's session lookup.
 */
export const queryCensusLogger: Logger = {
	logQuery(query) {
		observeQuery(query);
	},
};

files.src/lib/server/db/schema-filter.gate.tes:
/**
 * `drizzle.config.ts`'s `schemaFilter` must list exactly the namespaces the schema declares.
 *
 * A namespace missing from the filter is not an error `db:push` reports — it is one it
 * silently skips, so the tables simply never appear and the first symptom is a runtime
 * "relation does not exist" against production. CLAUDE.md has warned about this in prose
 * since the beginning; the rename of `rag` → `retrieval` is what proved prose insufficient,
 * because the schema was updated and the filter was not.
 *
 * This file lives one level ABOVE `schema/`: drizzle-kit loads every top-level file of the
 * schema directory as schema (non-recursively), and vitest 4's CommonJS entry throws when
 * required that way — a test inside `schema/` breaks `db:push` itself.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

const ROOT = process.cwd();

function declaredNamespaces(): string[] {
	const found = new Set<string>();
	const walk = (dir: string) => {
		for (const entry of readdirSync(dir)) {
			const path = join(dir, entry);
			if (statSync(path).isDirectory()) walk(path);
			else if (path.endsWith('.ts') && !path.endsWith('.test.ts')) {
				for (const m of readFileSync(path, 'utf8').matchAll(/pgSchema\('([a-z_]+)'\)/g)) found.add(m[1]);
			}
		}
	};
	walk(join(ROOT, 'src/lib/server/db/schema'));
	return [...found].sort();
}

function filteredNamespaces(): string[] {
	const source = readFileSync(join(ROOT, 'drizzle.config.ts'), 'utf8');
	const block = source.match(/schemaFilter:\s*\[([^\]]*)\]/s);
	if (!block) throw new Error('drizzle.config.ts has no schemaFilter array');
	return [...block[1].matchAll(/'([a-z_]+)'/g)].map((m) => m[1]).sort();
}

describe('drizzle schemaFilter', () => {
	it('lists exactly the declared pgSchema namespaces', () => {
		expect(filteredNamespaces()).toEqual(declaredNamespaces());
	});
});

