/**
 * Architecture drafts: saved architecture files kept in this browser only.
 *
 * Local-first on purpose (plan §4.7): no database schema and no sign-in for a drafting tool,
 * and the UI says plainly that drafts live in this browser. Storage is injected
 * (`() => Storage | null`, the `form-draft.ts` convention), so private mode, a full quota or
 * SSR degrade to "nothing saved" instead of an exception.
 *
 * Every read goes through `parseArchitectureFile`: a stored draft is untrusted input like any
 * import (another tab, an older version, a hand edit). A corrupt or unsupported entry is
 * reported as such, never thrown, and never silently replaced.
 *
 * The contract is the file text, not this store: a server-side store can replace it later
 * without touching the architecture model.
 */
import {
	type ArchitectureFile,
	type ModelIssue,
	parseArchitectureFile,
	stringifyArchitectureFile,
} from '#patterns/architecture-engineering/index.ts';

const PREFIX = 'v10r:studio:architecture';
const INDEX_KEY = `${PREFIX}:index`;
const WORKING_KEY = `${PREFIX}:working`;
const draftKey = (id: string) => `${PREFIX}:draft:${id}`;

export interface ArchitectureDraftEntry {
	id: string;
	name: string;
	savedAt: string;
	derived_from?: string;
}

export type DraftRead =
	| { ok: true; file: ArchitectureFile }
	| { ok: false; reason: 'missing' | 'corrupt'; issues: ModelIssue[] };

export type DraftWrite = { ok: true } | { ok: false; reason: 'unavailable' | 'quota' };

function readIndex(storage: Storage): ArchitectureDraftEntry[] {
	let raw: string | null;
	try {
		raw = storage.getItem(INDEX_KEY);
	} catch {
		return [];
	}
	if (!raw) return [];
	try {
		const parsed: unknown = JSON.parse(raw);
		if (!Array.isArray(parsed)) return [];
		return parsed.filter(
			(entry): entry is ArchitectureDraftEntry =>
				typeof entry === 'object' &&
				entry !== null &&
				typeof entry.id === 'string' &&
				typeof entry.name === 'string' &&
				typeof entry.savedAt === 'string',
		);
	} catch {
		return [];
	}
}

function write(storage: Storage, key: string, value: string): DraftWrite {
	try {
		storage.setItem(key, value);
		return { ok: true };
	} catch {
		return { ok: false, reason: 'quota' };
	}
}

function read(storage: Storage | null, key: string): DraftRead {
	if (!storage) return { ok: false, reason: 'missing', issues: [] };
	let text: string | null;
	try {
		text = storage.getItem(key);
	} catch {
		return { ok: false, reason: 'missing', issues: [] };
	}
	if (text === null) return { ok: false, reason: 'missing', issues: [] };
	const parsed = parseArchitectureFile(text);
	return parsed.ok ? { ok: true, file: parsed.file } : { ok: false, reason: 'corrupt', issues: parsed.issues };
}

export function createArchitectureDraftStore(getStorage: () => Storage | null, now: () => Date = () => new Date()) {
	return {
		/** Saved drafts, most recent first. */
		list(): ArchitectureDraftEntry[] {
			const storage = getStorage();
			return storage
				? readIndex(storage).sort((a, b) => (a.savedAt < b.savedAt ? 1 : a.savedAt > b.savedAt ? -1 : 0))
				: [];
		},
		save(file: ArchitectureFile): DraftWrite {
			const storage = getStorage();
			if (!storage) return { ok: false, reason: 'unavailable' };
			const written = write(storage, draftKey(file.model.id), stringifyArchitectureFile(file));
			if (!written.ok) return written;
			const entry: ArchitectureDraftEntry = {
				id: file.model.id,
				name: file.model.name,
				savedAt: now().toISOString(),
				...(file.model.derived_from ? { derived_from: file.model.derived_from } : {}),
			};
			const index = readIndex(storage).filter((existing) => existing.id !== entry.id);
			return write(storage, INDEX_KEY, JSON.stringify([...index, entry]));
		},
		load(id: string): DraftRead {
			return read(getStorage(), draftKey(id));
		},
		remove(id: string): void {
			const storage = getStorage();
			if (!storage) return;
			try {
				storage.removeItem(draftKey(id));
			} catch {
				// Removing from unavailable storage has nothing to undo.
			}
			write(storage, INDEX_KEY, JSON.stringify(readIndex(storage).filter((entry) => entry.id !== id)));
		},
		/** The unsaved working copy, kept on every edit so a reload or a crash loses nothing. */
		saveWorking(file: ArchitectureFile): DraftWrite {
			const storage = getStorage();
			if (!storage) return { ok: false, reason: 'unavailable' };
			return write(storage, WORKING_KEY, stringifyArchitectureFile(file));
		},
		loadWorking(): DraftRead {
			return read(getStorage(), WORKING_KEY);
		},
	};
}

export type ArchitectureDraftStore = ReturnType<typeof createArchitectureDraftStore>;

/** `localStorage` when the browser offers it; `null` on the server or when access throws. */
export function browserStorage(): Storage | null {
	try {
		return typeof localStorage === 'undefined' ? null : localStorage;
	} catch {
		return null;
	}
}

import { describe, expect, it } from 'vitest';
import { createArchitectureModel, stringifyArchitectureFile } from '#patterns/architecture-engineering/index.ts';
import { createArchitectureDraftStore } from './architecture-drafts.ts';
import { createArchitectureStudio } from './architecture-studio.svelte.ts';

function memoryStorage(): Storage {
	const map = new Map<string, string>();
	return {
		get length() {
			return map.size;
		},
		clear: () => map.clear(),
		getItem: (k) => map.get(k) ?? null,
		key: (i) => [...map.keys()][i] ?? null,
		removeItem: (k) => void map.delete(k),
		setItem: (k, v) => void map.set(k, v),
	};
}

function setup(storage: Storage = memoryStorage()) {
	let clock = 1_000_000;
	const store = createArchitectureDraftStore(
		() => storage,
		() => new Date(clock),
	);
	const studio = createArchitectureStudio({ store, now: () => clock });
	studio.hydrate();
	return { studio, store, storage, tick: (ms: number) => (clock += ms) };
}

describe('architecture studio state', () => {
	it('Explore → Design builds a model from the recommendation, as one undoable step', () => {
		const { studio } = setup();
		studio.applyExample('background-media-conversion');
		expect(studio.exampleId).toBe('background-media-conversion');
		studio.transferToDesign();
		expect(studio.model.nodes.length).toBeGreaterThan(0);
		expect(studio.notice?.text).toBe('transferred');
		studio.undo();
		expect(studio.model.nodes).toEqual([]);
	});

	it('editing a factor clears the example; reset returns every factor to unknown', () => {
		const { studio } = setup();
		studio.applyExample('lightweight-rest-api');
		studio.setFactor('latency', 'interactive');
		expect(studio.exampleId).toBeNull();
		studio.resetProfile();
		expect(studio.recommendation.unknown_factors.length).toBe(Object.keys(studio.profile).length);
	});

	it('adds, connects, refuses invalid changes, and undoes/redoes them', () => {
		const { studio, tick } = setup();
		const a = studio.addNode('browser-app') as string;
		tick(1000);
		const b = studio.addNode('app-server') as string;
		expect(studio.selection).toEqual({ type: 'node', id: b });
		expect(studio.connect(a, a)).toBeNull();
		expect(studio.refusal).toBe('connection.self');
		const link = studio.connect(a, b);
		expect(link).not.toBeNull();
		expect(studio.refusal).toBeNull();
		expect(studio.model.connections).toHaveLength(1);

		studio.select({ type: 'node', id: b });
		studio.removeSelected();
		expect(studio.model.connections).toHaveLength(0);
		expect(studio.selection).toBeNull();
		studio.undo();
		expect(studio.model.nodes.map((node) => node.id)).toContain(b);
		expect(studio.model.connections).toHaveLength(1);
		studio.redo();
		expect(studio.model.nodes.map((node) => node.id)).not.toContain(b);
	});

	it('coalesces typing into one undo step', () => {
		const { studio, tick } = setup();
		const id = studio.addNode('app-server') as string;
		const original = studio.model.nodes.find((node) => node.id === id)?.label;
		studio.updateNode(id, { label: 'A' }, 'label');
		tick(100);
		studio.updateNode(id, { label: 'Ap' }, 'label');
		tick(100);
		studio.updateNode(id, { label: 'Api' }, 'label');
		studio.undo();
		expect(studio.model.nodes.find((node) => node.id === id)?.label).toBe(original);
	});

	it('keeps the layout apart from the model: a move changes positions only', () => {
		const { studio } = setup();
		const id = studio.addNode('app-server') as string;
		const before = studio.model;
		studio.moveNode(id, { x: 400, y: 200 });
		expect(studio.model).toBe(before);
		expect(studio.layout.positions[id]).toEqual({ x: 400, y: 200 });
	});

	it('every accepted change survives a reload through the working copy', () => {
		const storage = memoryStorage();
		const first = setup(storage).studio;
		first.addNode('relational-db');
		const reloaded = setup(storage).studio;
		expect(reloaded.model.nodes.map((node) => node.kind)).toEqual(['relational-db']);
	});

	it('a variant saves its baseline and records why it changed', () => {
		const { studio } = setup();
		studio.addNode('app-server');
		const baselineId = studio.model.id;
		studio.createVariant('With worker', 'Media conversion blocks requests');
		expect(studio.model.derived_from).toBe(baselineId);
		expect(studio.model.change_reason).toBe('Media conversion blocks requests');
		expect(studio.drafts.map((draft) => draft.id).sort()).toEqual([baselineId, studio.model.id].sort());
		expect(studio.draftModel(baselineId)?.id).toBe(baselineId);
	});

	it('import refuses invalid text and leaves the model untouched; valid text replaces it', () => {
		const { studio } = setup();
		studio.addNode('app-server');
		const before = studio.model;
		expect(studio.importText('{"model":{"format":1,"nodes":"<script>"}}')).toBe(false);
		expect(studio.model).toBe(before);
		expect(studio.notice?.text).toBe('import-invalid');

		const other = createArchitectureModel('imported', 'Imported');
		expect(studio.importText(stringifyArchitectureFile({ model: other }))).toBe(true);
		expect(studio.model.id).toBe('imported');
		expect(studio.exportText()).toContain('"imported"');
	});

	it('the evolution example becomes four comparable drafts', () => {
		const { studio } = setup();
		studio.loadEvolutionExample();
		expect(studio.drafts).toHaveLength(4);
		expect(studio.model.derived_from).toBeDefined();
	});
});

/**
 * The Studio's state for Architecture Engineering: the workload profile Explore edits, the
 * architecture model Design edits (with its separate layout), undo/redo, the selection, and
 * the local drafts. One instance lives in the area's `+layout.svelte`, so moving between
 * Explore, Design and Engineer keeps every edit.
 *
 * A thin reactive shell over the pure core in `#patterns/architecture-engineering`: every
 * model change is an operation that returns a new model or a refusal. The model is
 * `$state.raw`, replaced on every change and never deep-proxied (the attribute-editor
 * convention). Every accepted change is also written to the working copy, so a reload, a
 * crash or a closed tab loses nothing; "Save" files it as a named draft.
 */
import { getContext, setContext } from 'svelte';
import {
	type ArchitectureFile,
	type ArchitectureLayout,
	type ArchitectureModel,
	addConnection,
	addNode,
	type ConnectionPatch,
	checkArchitecture,
	createArchitectureModel,
	DECISION_CATALOG,
	deriveVariant,
	evolutionExample,
	exploreWorkload,
	findWorkloadExample,
	freeModelId,
	layoutByZone,
	type ModelIssue,
	type ModelOperation,
	type ModelRefusal,
	modelFromRecommendation,
	type NodeKind,
	type NodePatch,
	parseArchitectureFile,
	removeConnection,
	removeNode,
	stringifyArchitectureFile,
	unknownProfile,
	updateConnection,
	updateModelInfo,
	updateNode,
	type WorkloadFactor,
	type WorkloadProfile,
} from '#patterns/architecture-engineering/index.ts';
import type { ArchitectureDraftEntry, ArchitectureDraftStore } from './architecture-drafts.ts';

const HISTORY_LIMIT = 100;
/** Consecutive edits of the same field within this window are one undo step (typing a word). */
const COALESCE_MS = 800;

interface Snapshot {
	model: ArchitectureModel;
	layout: ArchitectureLayout;
}

export type StudioSelection = { type: 'node' | 'connection'; id: string } | null;

export interface StudioNotice {
	tone: 'info' | 'success' | 'error';
	text: string;
	issues?: ModelIssue[];
}

export interface ArchitectureStudioOptions {
	store: ArchitectureDraftStore;
	now?: () => number;
}

function emptyLayout(): ArchitectureLayout {
	return { format: 1, positions: {} };
}

export function createArchitectureStudio(options: ArchitectureStudioOptions) {
	const { store } = options;
	const now = options.now ?? (() => Date.now());

	let profile = $state<WorkloadProfile>(unknownProfile());
	let exampleId = $state<string | null>(null);
	const recommendation = $derived(exploreWorkload(DECISION_CATALOG, profile));

	let model = $state.raw<ArchitectureModel>(createArchitectureModel('untitled', 'Untitled architecture'));
	let layout = $state.raw<ArchitectureLayout>(emptyLayout());
	let past = $state.raw<Snapshot[]>([]);
	let future = $state.raw<Snapshot[]>([]);
	let lastEdit: { key: string; at: number } | null = null;
	let refusal = $state<ModelRefusal | null>(null);
	let selection = $state<StudioSelection>(null);
	let drafts = $state.raw<ArchitectureDraftEntry[]>([]);
	let notice = $state<StudioNotice | null>(null);
	/** True once the browser-only state (drafts, working copy) has been read. */
	let hydrated = $state(false);

	const findings = $derived(checkArchitecture(model));

	function persistWorking() {
		store.saveWorking({ model, layout });
	}

	/** Make `next` current, recording the previous state for undo. */
	function commit(next: Snapshot, coalesce?: string) {
		const at = now();
		const merging = coalesce !== undefined && lastEdit?.key === coalesce && at - lastEdit.at < COALESCE_MS;
		if (!merging) past = [...past, { model, layout }].slice(-HISTORY_LIMIT);
		lastEdit = coalesce === undefined ? null : { key: coalesce, at };
		future = [];
		model = next.model;
		layout = next.layout;
		persistWorking();
	}

	function apply(result: ModelOperation, coalesce?: string): string | null {
		if (!result.ok) {
			refusal = result.refusal;
			return null;
		}
		refusal = null;
		if (result.model === model) return result.id ?? null;
		const positions = { ...layout.positions };
		for (const id of Object.keys(positions))
			if (!result.model.nodes.some((node) => node.id === id)) delete positions[id];
		commit({ model: result.model, layout: { format: 1, positions } }, coalesce);
		return result.id ?? null;
	}

	/** Replace the whole document (open, import, transfer) — one undoable step. */
	function replace(file: ArchitectureFile) {
		commit({ model: file.model, layout: file.layout ?? layoutByZone(file.model) });
		selection = null;
		refusal = null;
	}

	function placeNew(id: string | null) {
		if (!id || layout.positions[id]) return;
		const count = model.nodes.length;
		layout = { format: 1, positions: { ...layout.positions, [id]: { x: 80 + (count % 4) * 60, y: 40 + count * 30 } } };
		persistWorking();
	}

	function travel(from: Snapshot[], to: Snapshot[]): [Snapshot[], Snapshot[]] | null {
		const target = from.at(-1);
		if (!target) return null;
		const next: [Snapshot[], Snapshot[]] = [from.slice(0, -1), [...to, { model, layout }]];
		model = target.model;
		layout = target.layout;
		lastEdit = null;
		refusal = null;
		if (selection && !exists(selection)) selection = null;
		persistWorking();
		return next;
	}

	function exists(target: NonNullable<StudioSelection>): boolean {
		return target.type === 'node'
			? model.nodes.some((node) => node.id === target.id)
			: model.connections.some((connection) => connection.id === target.id);
	}

	function newModelId(base: string): string {
		return freeModelId(
			`${base}-${now().toString(36)}`,
			drafts.map((entry) => entry.id),
		);
	}

	return {
		// ── Explore ──
		get profile() {
			return profile;
		},
		get exampleId() {
			return exampleId;
		},
		get recommendation() {
			return recommendation;
		},
		setFactor(factor: WorkloadFactor, value: string) {
			profile = { ...profile, [factor]: value } as WorkloadProfile;
			exampleId = null;
		},
		applyExample(id: string) {
			const example = findWorkloadExample(id);
			if (!example) return;
			profile = { ...example.profile };
			exampleId = id;
		},
		resetProfile() {
			profile = unknownProfile();
			exampleId = null;
		},
		/** Explore → Design: build a starting model from the current recommendation. */
		transferToDesign() {
			const example = exampleId ? findWorkloadExample(exampleId) : undefined;
			const id = newModelId('explored');
			const built = modelFromRecommendation(recommendation, id, example ? example.title : 'Explored architecture');
			replace({ model: built, layout: layoutByZone(built) });
			notice = { tone: 'success', text: 'transferred' };
		},

		// ── Design ──
		get model() {
			return model;
		},
		get layout() {
			return layout;
		},
		get findings() {
			return findings;
		},
		get refusal() {
			return refusal;
		},
		get selection() {
			return selection;
		},
		get canUndo() {
			return past.length > 0;
		},
		get canRedo() {
			return future.length > 0;
		},
		select(next: StudioSelection) {
			selection = next;
		},
		addNode(kind: NodeKind) {
			const id = apply(addNode(model, { kind }));
			placeNew(id);
			if (id) selection = { type: 'node', id };
			return id;
		},
		updateNode(id: string, patch: NodePatch, coalesce?: string) {
			return apply(updateNode(model, id, patch), coalesce ? `node:${id}:${coalesce}` : undefined);
		},
		connect(from: string, to: string) {
			const id = apply(addConnection(model, { from, to }));
			if (id) selection = { type: 'connection', id };
			return id;
		},
		updateConnection(id: string, patch: ConnectionPatch, coalesce?: string) {
			return apply(updateConnection(model, id, patch), coalesce ? `connection:${id}:${coalesce}` : undefined);
		},
		removeSelected() {
			if (!selection) return;
			const result =
				selection.type === 'node' ? removeNode(model, selection.id) : removeConnection(model, selection.id);
			apply(result);
			if (result.ok) selection = null;
		},
		/** A finished drag: one undo step. */
		moveNode(id: string, position: { x: number; y: number }) {
			const current = layout.positions[id];
			if (current && current.x === position.x && current.y === position.y) return;
			commit({ model, layout: { format: 1, positions: { ...layout.positions, [id]: position } } });
		},
		updateInfo(patch: Parameters<typeof updateModelInfo>[1], coalesce?: string) {
			apply(updateModelInfo(model, patch), coalesce ? `model:${coalesce}` : undefined);
		},
		autoLayout() {
			commit({ model, layout: layoutByZone(model) });
		},
		undo() {
			const moved = travel(past, future);
			if (moved) [past, future] = moved;
		},
		redo() {
			const moved = travel(future, past);
			if (moved) [future, past] = moved;
		},
		newModel() {
			replace({
				model: createArchitectureModel(newModelId('architecture'), 'Untitled architecture'),
				layout: emptyLayout(),
			});
		},

		// ── Drafts, files, variants ──
		get drafts() {
			return drafts;
		},
		get hydrated() {
			return hydrated;
		},
		get notice() {
			return notice;
		},
		dismissNotice() {
			notice = null;
		},
		/** Read browser-only state. Called once from the layout after mount. */
		hydrate() {
			drafts = store.list();
			const working = store.loadWorking();
			if (working.ok) {
				model = working.file.model;
				layout = working.file.layout ?? layoutByZone(working.file.model);
			} else if (working.reason === 'corrupt') {
				notice = { tone: 'error', text: 'working-corrupt', issues: working.issues };
			}
			hydrated = true;
		},
		save() {
			const result = store.save({ model, layout });
			drafts = store.list();
			notice = result.ok ? { tone: 'success', text: 'saved' } : { tone: 'error', text: `save-${result.reason}` };
		},
		open(id: string) {
			const result = store.load(id);
			if (!result.ok) {
				notice = { tone: 'error', text: `open-${result.reason}`, issues: result.issues };
				return;
			}
			replace(result.file);
			notice = null;
		},
		/** A saved draft's model, for comparison — `null` when it is missing or corrupt. */
		draftModel(id: string): ArchitectureModel | null {
			const result = store.load(id);
			return result.ok ? result.file.model : null;
		},
		deleteDraft(id: string) {
			store.remove(id);
			drafts = store.list();
		},
		/**
		 * Save the current model as the baseline (so the comparison can find it), then continue
		 * on a variant derived from it with the reason recorded.
		 */
		createVariant(name: string, reason: string) {
			const saved = store.save({ model, layout });
			if (!saved.ok) {
				notice = { tone: 'error', text: `save-${saved.reason}` };
				return;
			}
			const variant = deriveVariant(model, newModelId('variant'), name, reason);
			commit({ model: variant, layout });
			store.save({ model, layout });
			drafts = store.list();
			notice = { tone: 'success', text: 'variant-created' };
		},
		exportText(): string {
			return stringifyArchitectureFile({ model, layout });
		},
		importText(text: string): boolean {
			const parsed = parseArchitectureFile(text);
			if (!parsed.ok) {
				notice = { tone: 'error', text: 'import-invalid', issues: parsed.issues.slice(0, 8) };
				return false;
			}
			replace(parsed.file);
			notice = { tone: 'success', text: 'imported' };
			return true;
		},
		/** Load the four-stage evolution example as saved drafts and open its last stage. */
		loadEvolutionExample() {
			const stages = evolutionExample();
			for (const stage of stages) store.save({ model: stage, layout: layoutByZone(stage) });
			drafts = store.list();
			const last = stages[stages.length - 1];
			replace({ model: last, layout: layoutByZone(last) });
			notice = { tone: 'success', text: 'example-loaded' };
		},
	};
}

export type ArchitectureStudio = ReturnType<typeof createArchitectureStudio>;

const KEY = Symbol('architecture-studio');

export function provideArchitectureStudio(studio: ArchitectureStudio): ArchitectureStudio {
	setContext(KEY, studio);
	return studio;
}

export function useArchitectureStudio(): ArchitectureStudio {
	const studio = getContext<ArchitectureStudio | undefined>(KEY);
	if (!studio) throw new Error('useArchitectureStudio: no studio in context (render inside the architecture layout)');
	return studio;
}

